      "path": "hindsight-integrations/coding-agents/src/dsh.ts",
      "content": "/**\n * DeepSeek Harness (`dsh`) entrypoint — a native Cordis plugin.\n *\n * dsh is plugin-first: its canonical extension surface is a set of typed lifecycle events, and its\n * Claude Code / Codex hook bridges are just translators onto that same surface. So this integration\n * binds the events directly instead of installing hook binaries — a bridge would cost the same\n * install (neither bridge ships in a default profile) while losing the transcript, the session id\n * and the awaited stop boundary.\n *\n *   agent/session-start  -> RuntimeCore.seedIfCold      (cold-check + background git/codebase seed)\n *   agent/pre-step       -> RuntimeCore.onPrompt        (recall) + the injection as a sourced message\n *   agent/turn-stopping  -> RuntimeCore.onSessionIdle   (write-back of the completed exchange)\n *   ctx.tools            -> the hindsight_* knowledge suite, registered natively\n *\n * ONE dsh PROCESS SERVES MANY WORKSPACES. Unlike opencode/Kilo/Cline — one process, one project —\n * dsh's Web UI creates sessions in whatever directory the user picks, each with its own\n * `session.header.cwd`. Memory is per-repo, so a RuntimeCore (bank, client, seed) is built PER\n * WORKSPACE ROOT and cached, never once per process.\n *\n * The plugin imports NOTHING from dsh at all: every host shape is structurally typed here, and the\n * tool definitions are built in dsh's own registry shape rather than through its `defineTool`\n * builder (see `toDshParameters`). So there is no dsh package for pnpm to resolve inside a profile,\n * and no version to keep in step — any dsh whose event names still match can load this file.\n */\nimport { randomUUID } from \"node:crypto\";\nimport { resolveHostMemory } from \"./core/host-client\";\nimport { diag } from \"./core/diag\";\nimport type { ToolSpec } from \"./core/knowledge-tools\";\nimport { log } from \"./core/log\";\nimport { RuntimeCore } from \"./core/runtime\";\nimport { HINDSIGHT_PLUGIN, readDshEvents, type DshSessionEvent } from \"./core/transcript-dsh\";\n\nconst HARNESS = \"dsh\";\n\n/** Cordis plugin name (loader diagnostics, and the `source.plugin` on everything we inject). */\nexport const name = HINDSIGHT_PLUGIN;\n\n/** The agent registry owns the lifecycle events below; without it there is nothing to bind. */\nexport const inject = [\"agents\"];\n\n// ── host shapes (structural: this package must not depend on dsh's packages) ─────\n\ninterface DshSession {\n  readonly header: { readonly id: string; readonly cwd?: string; readonly origin?: string };\n  /**\n   * Legacy in-memory event log. Present on DeepSeek Harness < alpha.4; removed in alpha.4+.\n   * Prefer {@link snapshotEvents} when available.\n   */\n  readonly events?: readonly DshSessionEvent[];\n  /** Public accessor on DeepSeek Harness alpha.4+ (replaces the removed `events` property). */\n  snapshotEvents?(): readonly DshSessionEvent[];\n  /** How many leading events a FORK copied from its parent (`session/fork`); 0 or absent otherwise.\n   *  Persisted with the session, so it survives a restart. */\n  readonly inheritedEventCount?: number;\n}\n\ninterface DshAgent {\n  readonly session: DshSession;\n}\n\n/** A `user/message` as dsh's pre-step decision carries it. */\ninterface DshUserMessage {\n  role: \"user\";\n  content: { type: string; text?: string }[];\n  source: { kind: string; form?: string };\n  id?: string;\n}\n\ntype PreStepDecision =\n  | { kind: \"enter\"; messages: DshUserMessage[] }\n  | { kind: \"reject\"; [key: string]: unknown };\n\ninterface PreStepPayload {\n  agent: DshAgent;\n  signal: AbortSignal;\n}\n\n/** The Cordis context surface this plugin uses. */\ninterface DshContext {\n  on(\n    event: \"agent/session-start\",\n    listener: (payload: { agent: DshAgent }) => void\n  ): (() => void) | void;\n  on(\n    event: \"agent/pre-step\",\n    listener: (\n      payload: PreStepPayload,\n      next: () => Promise<PreStepDecision>\n    ) => Promise<PreStepDecision>,\n    options?: { prepend?: boolean }\n  ): (() => void) | void;\n  on(\n    event: \"agent/turn-stopping\",\n    listener: (payload: { agent: DshAgent }) => Promise<void> | void\n  ): (() => void) | void;\n  on(\n    event: \"agent/disposed\",\n    listener: (payload: { agent: DshAgent }) => void\n  ): (() => void) | void;\n  inject(names: string[], callback: (ctx: DshToolContext) => void): void;\n}\n\ninterface DshToolContext {\n  tools: {\n    register(definition: unknown): void;\n    /** Registry introspection; used only to log what the host ended up exposing. */\n    schemas?(): { name: string }[];\n  };\n}\n\n/** `exec` as a dsh tool body receives it (only the caller matters to us). */\ninterface DshToolRunContext {\n  readonly agent?: DshAgent;\n}\n\n// ── per-workspace runtime cache ─────────────────────────────────────────────────\n\nexport interface Workspace {\n  core: RuntimeCore;\n  root: string;\n  /** Started by the first SESSION in this repo, then shared by every later one. */\n  seeded?: Promise<void>;\n  tools?: ToolSpec[];\n}\n\n/** `null` caches \"memory is off for this repo\" so a disabled bank isn't re-derived every turn. */\nconst workspaces = new Map<string, Workspace | null>();\n/**\n * sessionId -> agent, so a core's transcript source (which only receives the id) can read the live\n * log back on stop. `agent/disposed` is what bounds it: an agent holds its whole session log, so\n * dropping the entry when the host disposes the agent is what keeps a long-lived Web server from\n * pinning every session it ever opened.\n */\nconst liveAgents = new Map<string, DshAgent>();\n\n/**\n * Prefer `session.snapshotEvents()` (DeepSeek Harness alpha.4+); fall back to the legacy\n * `session.events` property so older hosts keep working. Missing both yields an empty log —\n * which is exactly the alpha.4 breakage when callers still read `events` alone.\n */\nexport function dshSessionEvents(\n  session: Pick<DshSession, \"snapshotEvents\" | \"events\">\n): readonly DshSessionEvent[] {\n  return session.snapshotEvents?.() ?? session.events ?? [];\n}\n\n/**\n * The events this session produced itself — what its write-back saves. A fork saves only its new\n * turns (#5940): the prefix it inherited is the parent's conversation, which the parent already\n * stores, and the child's first write-back used to send all of it again under its own document,\n * re-extracting history the bank already held. The full log is still what the model sees, so\n * everything else (the injection dedupe below) reads `dshSessionEvents`.\n */\nexport function ownEvents(\n  session: Pick<DshSession, \"snapshotEvents\" | \"events\" | \"inheritedEventCount\">\n): readonly DshSessionEvent[] {\n  return dshSessionEvents(session).slice(session.inheritedEventCount ?? 0);\n}\n\n/** Where a session is working. dsh records it on the session header; a session without one is rare. */\nfunction workspaceRoot(agent: DshAgent): string {\n  return agent.session.header.cwd || process.cwd();\n}\n\n/**\n * The memory runtime for one workspace root, built on first use.\n *\n * Bank derivation and the per-bank opt-out live here rather than in `apply`, because the plugin\n * loads before any session exists and the process may end up serving several unrelated\n * repositories. Building one has NO side effect: the seed is started by `ensureSeeded` when a\n * session actually opens, so merely registering the tools never seeds the launch directory.\n */\nfunction workspaceFor(root: string): Workspace | undefined {\n  const cached = workspaces.get(root);\n  if (cached !== undefined) return cached ?? undefined;\n\n  // One shared builder for every long-lived host (core/host-client.ts): the global switch, the\n  // per-bank opt-out and `optInOnly` all land in `cfg.disabled`.\n  const { cfg, bankId, client } = resolveHostMemory(HARNESS, root);\n  if (cfg.disabled) {\n    workspaces.set(root, null); // inert: same agent, no memory (baseline parity)\n    return undefined;\n  }\n  // The 5th argument is this host's whole reason for existing here: RuntimeCore binds the\n  // knowledge tools (and retain stamps) to the workspace it is given, and dsh's process cwd is the\n  // launch directory, routinely a different repository from the session's.\n  const core = new RuntimeCore(client, bankId, cfg, HARNESS, root);\n  // The write-back path reads the log back off the live agent — dsh keeps the whole session in\n  // memory, so unlike opencode there is nothing to refetch over HTTP.\n  core.setTranscriptSource(async (sessionId) => {\n    const agent = liveAgents.get(sessionId);\n    return agent ? readDshEvents(ownEvents(agent.session)) : [];\n  });\n  const workspace: Workspace = { core, root };\n  workspaces.set(root, workspace);\n  return workspace;\n}\n\n/**\n * Start this repo's cold-check + background seed once.\n *\n * Fire-and-forget by design: `agent/session-start` is an emit that no extension point awaits, and\n * the Web UI must not wait on a network round-trip to open a session. Nothing the first prompt\n * needs comes from here — it builds its own knowledge preamble from that session's page list.\n */\nfunction ensureSeeded(workspace: Workspace): void {\n  workspace.seeded ??= workspace.core.seedIfCold(workspace.root);\n}\n\nfunction workspaceForAgent(agent: DshAgent): Workspace | undefined {\n  // A subagent session is a child of a conversation we already track: injecting into it would pay\n  // for a second recall per delegation, and retaining it would file a fragment of a session that\n  // the parent already stores in full.\n  if (agent.session.header.origin === \"subagent\") return undefined;\n  return workspaceFor(workspaceRoot(agent));\n}\n\n// ── message helpers ─────────────────────────────────────────────────────────────\n\n/**\n * The human text in this step's claimed batch.\n *\n * `agent/pre-step` fires before EVERY step, including tool continuations that claimed no new input,\n * and other plugins contribute their own context messages to the same batch (V3 hosts tag them\n * `kind: 'plugin'`, V4 hosts use a producer-owned kind such as `time-context`). Only a\n * `kind: 'user'` message is a prompt worth recalling on.\n */\nfunction promptOf(messages: readonly DshUserMessage[]): string {\n  return (messages || [])\n    .filter((message) => message?.source?.kind === \"user\")\n    .flatMap((message) => message.content || [])\n    .filter((block) => block?.type === \"text\" && block.text)\n    .map((block) => block.text!)\n    .join(\"\\n\")\n    .trim();\n}\n\n/**\n * Build the injected memory message.\n *\n * `form: 'recall'` is dsh's own vocabulary for retrieved context, so its UI renders the block as\n * recalled material rather than as something the user typed. Session format V4 requires injected\n * messages to use a producer-owned source kind; `plugin:hindsight` is the canonical fallback name\n * for an unregistered plugin. The non-user source also keeps the block out of a write-back.\n */\nfunction injectionMessage(text: string): DshUserMessage {\n  return {\n    id: randomUUID(),\n    role: \"user\",\n    content: [{ type: \"text\", text }],\n    source: { kind: `plugin:${HINDSIGHT_PLUGIN}`, form: \"recall\" },\n  };\n}\n\n/**\n * The text of the last memory block this session's history carries, if any.\n *\n * dsh keeps every injected message in the history it sends, so re-appending an unchanged block (the\n * per-turn roster) only stacks identical copies (#5026). This used to be remembered in a map keyed\n * by session id, which a fork (new id, inherited history) and a restart (empty map) both reset while\n * the block was still in the history — so the next unchanged recall appended a second copy (#5940).\n * Reading it off the history itself is what the model will actually see.\n */\nexport function lastInjectedText(events: readonly DshSessionEvent[]): string | undefined {\n  for (let i = events.length - 1; i >= 0; i--) {\n    const event = events[i];\n    if (event?.type !== \"user/message\") continue;\n    const message = event.data as Partial<DshUserMessage> | undefined;\n    if (message?.source?.kind !== `plugin:${HINDSIGHT_PLUGIN}`) continue;\n    return (message.content ?? []).map((block) => block.text ?? \"\").join(\"\\n\");\n  }\n  return undefined;\n}\n\n// ── the lifecycle, testable without a dsh host ──────────────────────────────────\n\n/**\n * The three lifecycle handlers, over an injectable workspace resolver. `apply` binds these to the\n * real Cordis events; the tests drive them with a stand-in agent and core.\n */\nexport function createDshHooks(resolve: (agent: DshAgent) => Workspace | undefined) {\n  return {\n    sessionStart({ agent }: { agent: DshAgent }): void {\n      const workspace = resolve(agent);\n      if (!workspace) return;\n      liveAgents.set(agent.session.header.id, agent);\n      ensureSeeded(workspace);\n    },\n\n    async preStep(\n      { agent, signal }: PreStepPayload,\n      next: () => Promise<PreStepDecision>\n    ): Promise<PreStepDecision> {\n      const decision = await next();\n      if (decision.kind !== \"enter\" || signal.aborted) return decision;\n      const workspace = resolve(agent);\n      if (!workspace) return decision;\n      const sessionId = agent.session.header.id;\n      liveAgents.set(sessionId, agent);\n      // A resumed session gets no `agent/session-start` in some compositions; seeding here too\n      // keeps the cold-check exactly-once without depending on which events a host fired.\n      ensureSeeded(workspace);\n      // No new human input means a tool continuation: recall already ran for this turn, and its\n      // block is already in the history the model is about to be sent.\n      const prompt = promptOf(decision.messages);\n      if (!prompt) return decision;\n      await workspace.core.onPrompt(sessionId, prompt);\n      const injection = workspace.core.getInjection(sessionId);\n      if (!injection) {\n        diag(HARNESS, \"inject_empty\", { session: sessionId });\n        return decision;\n      }\n      if (injection === lastInjectedText(dshSessionEvents(agent.session))) {\n        diag(HARNESS, \"inject_unchanged\", { session: sessionId });\n        return decision;\n      }\n      diag(HARNESS, \"inject_ok\", { session: sessionId, chars: injection.length });\n      return { kind: \"enter\", messages: [...decision.messages, injectionMessage(injection)] };\n    },\n\n    async turnStopping({ agent }: { agent: DshAgent }): Promise<void> {\n      const workspace = resolve(agent);\n      if (!workspace) return;\n      const sessionId = agent.session.header.id;\n      liveAgents.set(sessionId, agent);\n      // The stop boundary is the only moment the completed exchange is readable, so this bypasses\n      // the turn cadence exactly like the opencode idle path it shares (`onSessionIdle`).\n      await workspace.core.onSessionIdle(sessionId);\n    },\n\n    disposed({ agent }: { agent: DshAgent }): void {\n      liveAgents.delete(agent.session.header.id);\n    },\n  };\n}\n\n// ── native tools ────────────────────────────────────────────────────────────────\n\n/**\n * Project one harness-agnostic ToolSpec's input onto the JSON Schema dsh's registry stores.\n *\n * dsh's own `defineTool` is a pure builder — it compiles this exact schema shape and wraps the\n * callbacks — and `ctx.tools.register` validates a definition structurally, not by module identity.\n * Building the schema here therefore keeps the plugin free of a `@deepseek-ai/dsh-tools` dependency\n * that pnpm would have to resolve inside the profile, at the cost of one small projection.\n *\n * Our specs state their input as a Zod raw shape (the MCP dialect every harness shares) and are\n * deliberately flat: required or optional strings. Optionality and the description are the only two\n * facts to carry across; a parameter that is ever anything but a string fails loudly here rather\n * than registering a mis-typed tool.\n */\nexport function toDshParameters(spec: ToolSpec): Record<string, unknown> {\n  const properties: Record<string, unknown> = {};\n  const required: string[] = [];\n  for (const [key, schema] of Object.entries(spec.inputSchema)) {\n    const zod = schema as {\n      def?: { type?: string; innerType?: { def?: { type?: string } } };\n      description?: string;\n      isOptional?: () => boolean;\n    };\n    // `.optional()` wraps the real type, so unwrap before checking it — otherwise every optional\n    // parameter would pass the guard below whatever it actually holds.\n    const inner = zod.def?.type === \"optional\" ? zod.def.innerType?.def?.type : zod.def?.type;\n    if (inner !== undefined && inner !== \"string\") {\n      throw new Error(\n        `hindsight tool ${spec.name}: dsh projection supports string parameters only`\n      );\n    }\n    properties[key] = {\n      type: \"string\",\n      ...(zod.description ? { description: zod.description } : {}),\n    };\n    if (typeof zod.isOptional !== \"function\" || !zod.isOptional()) required.push(key);\n  }\n  return { type: \"object\", properties, ...(required.length ? { required } : {}) };\n}\n\n/** The tool bodies return MCP-shaped results and never throw; dsh wants a value or a throw. */\nasync function runSpec(spec: ToolSpec, args: Record<string, unknown>): Promise<string> {\n  const result = await spec.handler(args);\n  const text = (result.content || []).map((block) => block.text).join(\"\\n\");\n  // dsh normalizes a thrown tool body into an isError result with this message, which is exactly\n  // what our isError:true means — mapping it any other way would report a failure as a success.\n  if (result.isError) throw new Error(text || \"hindsight tool failed\");\n  return text;\n}\n\n/**\n * Register the hindsight_* suite on `ctx.tools`.\n *\n * The dsh tools registry is host+per-scope layered, so a host-plane registration is visible to\n * every agent — including the Web surface's per-session agent presets. Each call resolves the bank\n * from the CALLING agent's workspace, because one process serves many repositories.\n */\nfunction registerTools(toolCtx: DshToolContext, fallbackRoot: string): void {\n  // The registry is populated at plugin load, before any session exists, so the NAMES and schemas\n  // come from the launch directory's workspace and each call rebinds to its own caller's bank. The\n  // one consequence: if memory is off for the launch directory specifically (a `banks.<id>`\n  // opt-out) the tools are absent even for other repositories this process later serves.\n  const template = workspaceFor(fallbackRoot);\n  if (!template) return; // memory disabled where this process was launched\n  for (const spec of specsOf(template)) {\n    toolCtx.tools.register({\n      name: spec.name,\n      description: spec.description,\n      parameters: toDshParameters(spec),\n      output: {\n        schema: { type: \"string\" },\n        render: (_args: unknown, value: string) => [{ type: \"text\", text: value }],\n      },\n      async execute(args: Record<string, unknown>, exec: DshToolRunContext): Promise<string> {\n        // Bind to the caller's repository, not to whichever workspace happened to load first.\n        const workspace = exec?.agent ? workspaceForAgent(exec.agent) : template;\n        if (!workspace) return \"Hindsight memory is disabled for this workspace.\";\n        const bound = specsOf(workspace).find((candidate) => candidate.name === spec.name);\n        if (!bound) return `Hindsight tool ${spec.name} is unavailable.`;\n        return runSpec(bound, args);\n      },\n    });\n  }\n  // Log what the HOST sees, not just what we handed it: a tool that registers cleanly but never\n  // reaches a model is the failure mode worth catching, and this is the one line that shows it.\n  const exposed = toolCtx.tools.schemas?.() ?? [];\n  log.debug(HARNESS, \"tools registered\", {\n    count: specsOf(template).length,\n    hostCatalog: exposed.length,\n    hindsight: exposed.filter((schema) => schema.name?.startsWith(\"hindsight_\")).length,\n  });\n}\n\n/** The tool specs for one workspace, built once (each closes over that bank's client and root). */\nfunction specsOf(workspace: Workspace): ToolSpec[] {\n  workspace.tools ??= workspace.core.toolSpecs();\n  return workspace.tools;\n}\n\n// ── cordis entrypoint ───────────────────────────────────────────────────────────\n\n/**\n * Bind the memory lifecycle for the lifetime of `ctx`. Every listener is fail-open: RuntimeCore\n * never throws, and a workspace we cannot resolve simply leaves that session unmemoried.\n */\nexport function apply(ctx: DshContext): void {\n  const hooks = createDshHooks(workspaceForAgent);\n  ctx.on(\"agent/session-start\", hooks.sessionStart);\n  // `prepend: true` puts this listener outermost, so the injection is appended AFTER every other\n  // contributor's messages — the memory block reads last, closest to the model's turn.\n  ctx.on(\"agent/pre-step\", hooks.preStep, { prepend: true });\n  ctx.on(\"agent/turn-stopping\", hooks.turnStopping);\n  ctx.on(\"agent/disposed\", hooks.disposed);\n  // The tools registry is optional: a composition without it (a bare headless assembly) still gets\n  // recall, injection and write-back.\n  ctx.inject([\"tools\"], (toolCtx) => {\n    registerTools(toolCtx, process.cwd());\n  });\n}\n\nexport default { name, inject, apply };\n"
    },
    {
      "path": "hindsight-integrations/coding-agents/src/dsh.test.ts",
      "content": "import { describe, expect, it, vi } from \"vitest\";\nimport {\n  createDshHooks,\n  dshSessionEvents,\n  ownEvents,\n  toDshParameters,\n  type Workspace,\n} from \"./dsh\";\nimport { readDshEvents } from \"./core/transcript-dsh\";\nimport type { ToolSpec } from \"./core/knowledge-tools\";\nimport { z } from \"zod\";\n\nconst session = (id: string, extra: Record<string, unknown> = {}) => ({\n  header: { id, cwd: \"/repo\", ...extra },\n  events: [] as unknown[],\n});\n\nconst agentWith = (id: string, extra: Record<string, unknown> = {}) =>\n  ({ session: session(id, extra) }) as never;\n\nconst userMessage = (text: string) => ({\n  id: `m-${text}`,\n  role: \"user\" as const,\n  content: [{ type: \"text\", text }],\n  source: { kind: \"user\" },\n});\n\nconst pluginMessage = (text: string) => ({\n  id: `p-${text}`,\n  role: \"user\" as const,\n  content: [{ type: \"text\", text }],\n  source: { kind: \"plugin\", plugin: \"@deepseek-ai/dsh-system-prompt\" },\n});\n\nfunction fakeWorkspace(core: Partial<Workspace[\"core\"]>): Workspace {\n  return { core: core as Workspace[\"core\"], root: \"/repo\", seeded: Promise.resolve() };\n}\n\nconst enter = (messages: unknown[]) => async () => ({ kind: \"enter\" as const, messages }) as never;\n\ndescribe(\"dsh pre-step injection\", () => {\n  it(\"recalls on the human prompt and appends the memory as a sourced message\", async () => {\n    const core = {\n      onPrompt: vi.fn(async () => {}),\n      getInjection: vi.fn(() => \"<hindsight_memory>past decision</hindsight_memory>\"),\n      seedIfCold: vi.fn(async () => {}),\n    };\n    const hooks = createDshHooks(() => fakeWorkspace(core));\n\n    const decision = await hooks.preStep(\n      { agent: agentWith(\"s-1\"), signal: new AbortController().signal },\n      enter([userMessage(\"why did we roll back?\"), pluginMessage(\"Current runtime context…\")])\n    );\n\n    expect(core.onPrompt).toHaveBeenCalledWith(\"s-1\", \"why did we roll back?\");\n    expect(decision.kind).toBe(\"enter\");\n    const appended = (decision as { messages: Record<string, any>[] }).messages.at(-1)!;\n    expect(appended).toMatchObject({\n      role: \"user\",\n      content: [{ type: \"text\", text: \"<hindsight_memory>past decision</hindsight_memory>\" }],\n    });\n    // Exact, not a partial match: dsh 0.1.7 (session format V4) aborts the turn on the retired\n    // `kind: \"plugin\"` wrapper, so no `plugin` field may ride along either.\n    expect(appended.source).toEqual({ kind: \"plugin:hindsight\", form: \"recall\" });\n    expect(appended.id).toEqual(expect.any(String));\n  });\n\n  it(\"does not re-append a block identical to the last one the history carries\", async () => {\n    // dsh keeps every injected message in the history it sends, so the same roster appended on\n    // every turn stacked up as N identical copies (#5026).\n    let block = \"<hindsight_knowledge_refresh>roster</hindsight_knowledge_refresh>\";\n    const core = {\n      onPrompt: vi.fn(async () => {}),\n      getInjection: vi.fn(() => block),\n      seedIfCold: vi.fn(async () => {}),\n    };\n    let hooks = createDshHooks(() => fakeWorkspace(core));\n    // The host logs every message a step enters, so later steps see the injected block.\n    const agents = new Map<string, { session: ReturnType<typeof session> }>();\n    const step = async (id: string, text: string, events?: unknown[]) => {\n      const agent = agents.get(id) ?? { session: session(id) };\n      if (events) agent.session.events = events;\n      agents.set(id, agent);\n      const decision = (await hooks.preStep(\n        { agent: agent as never, signal: new AbortController().signal },\n        enter([userMessage(text)])\n      )) as { messages: unknown[] };\n      for (const data of decision.messages)\n        agent.session.events.push({ type: \"user/message\", data });\n      return decision.messages;\n    };\n\n    expect(await step(\"s-1\", \"first\")).toHaveLength(2);\n    expect(await step(\"s-1\", \"second\")).toHaveLength(1);\n    // Another session gets its own copy.\n    expect(await step(\"s-2\", \"first\")).toHaveLength(2);\n    // A fork inherits the parent's history, block included, under a NEW session id (#5940).\n    expect(await step(\"s-fork\", \"first\", [...agents.get(\"s-1\")!.session.events])).toHaveLength(1);\n    // A restart rebuilds the plugin with nothing in memory, but the history still has the block.\n    hooks = createDshHooks(() => fakeWorkspace(core));\n    expect(await step(\"s-1\", \"after restart\")).toHaveLength(1);\n    // A changed block is injected again.\n    block = \"<hindsight_knowledge_refresh>new page</hindsight_knowledge_refresh>\";\n    expect(await step(\"s-1\", \"third\")).toHaveLength(2);\n  });\n\n  it(\"does not recall again on a tool continuation that claimed no new input\", async () => {\n    const core = {\n      onPrompt: vi.fn(async () => {}),\n      getInjection: vi.fn(() => \"memory\"),\n      seedIfCold: vi.fn(async () => {}),\n    };\n    const hooks = createDshHooks(() => fakeWorkspace(core));\n\n    const decision = await hooks.preStep(\n      { agent: agentWith(\"s-1\"), signal: new AbortController().signal },\n      enter([pluginMessage(\"Current runtime context…\")])\n    );\n\n    expect(core.onPrompt).not.toHaveBeenCalled();\n    expect((decision as { messages: unknown[] }).messages).toHaveLength(1);\n  });\n\n  it(\"leaves a rejected step and an aborted step untouched\", async () => {\n    const core = { onPrompt: vi.fn(async () => {}), getInjection: vi.fn(() => \"memory\") };\n    const hooks = createDshHooks(() => fakeWorkspace(core));\n\n    const rejected = await hooks.preStep(\n      { agent: agentWith(\"s-1\"), signal: new AbortController().signal },\n      async () => ({ kind: \"reject\" }) as never\n    );\n    const aborted = AbortSignal.abort();\n    const cancelled = await hooks.preStep(\n      { agent: agentWith(\"s-1\"), signal: aborted },\n      enter([userMessage(\"hello\")])\n    );\n\n    expect(rejected).toEqual({ kind: \"reject\" });\n    expect((cancelled as { messages: unknown[] }).messages).toHaveLength(1);\n    expect(core.onPrompt).not.toHaveBeenCalled();\n  });\n\n  it(\"passes the step through untouched when memory is off for the workspace\", async () => {\n    const hooks = createDshHooks(() => undefined);\n    const decision = await hooks.preStep(\n      { agent: agentWith(\"s-1\"), signal: new AbortController().signal },\n      enter([userMessage(\"hello\")])\n    );\n    expect((decision as { messages: unknown[] }).messages).toHaveLength(1);\n  });\n});\n\ndescribe(\"dsh write-back\", () => {\n  it(\"hands the completed exchange to the shared idle path at the stop boundary\", async () => {\n    const core = { onSessionIdle: vi.fn(async () => {}), seedIfCold: vi.fn(async () => {}) };\n    const hooks = createDshHooks(() => fakeWorkspace(core));\n\n    await hooks.turnStopping({ agent: agentWith(\"s-2\") });\n\n    expect(core.onSessionIdle).toHaveBeenCalledWith(\"s-2\");\n  });\n\n  it(\"skips subagent sessions the parent conversation already covers\", async () => {\n    const core = {\n      onSessionIdle: vi.fn(async () => {}),\n      onPrompt: vi.fn(async () => {}),\n      getInjection: vi.fn(() => \"memory\"),\n      seedIfCold: vi.fn(async () => {}),\n    };\n    // The real resolver applies this rule; assert it rather than the fake, so the test still means\n    // something if the hooks stop consulting the resolver for subagents.\n    const hooks = createDshHooks((agent) =>\n      (agent as unknown as { session: { header: { origin?: string } } }).session.header.origin ===\n      \"subagent\"\n        ? undefined\n        : fakeWorkspace(core)\n    );\n\n    await hooks.turnStopping({ agent: agentWith(\"child\", { origin: \"subagent\" }) });\n\n    expect(core.onSessionIdle).not.toHaveBeenCalled();\n  });\n});\n\ndescribe(\"dsh session start\", () => {\n  it(\"starts the repo seed exactly once, however many sessions open\", () => {\n    const core = { seedIfCold: vi.fn(async () => {}) };\n    const workspace = { core: core as never, root: \"/repo\" } as Workspace;\n    const hooks = createDshHooks(() => workspace);\n\n    hooks.sessionStart({ agent: agentWith(\"s-1\") });\n    hooks.sessionStart({ agent: agentWith(\"s-2\") });\n\n    expect(core.seedIfCold).toHaveBeenCalledOnce();\n    expect(core.seedIfCold).toHaveBeenCalledWith(\"/repo\");\n  });\n});\n\ndescribe(\"dshSessionEvents (alpha.4+ transcript source)\", () => {\n  const sampleEvents = [\n    {\n      type: \"user/message\",\n      time: Date.parse(\"2026-09-05T08:00:00Z\"),\n      data: {\n        id: \"m-1\",\n        role: \"user\",\n        content: [{ type: \"text\", text: \"why is chatDocs zero?\" }],\n        source: { kind: \"user\" },\n      },\n    },\n    {\n      type: \"assistant/message\",\n      time: Date.parse(\"2026-09-05T08:00:01Z\"),\n      data: {\n        message: {\n          role: \"assistant\",\n          content: [{ type: \"text\", text: \"session.events was removed.\" }],\n          source: { kind: \"model\" },\n        },\n      },\n    },\n  ];\n\n  it(\"reads snapshotEvents when the legacy events property is absent\", () => {\n    const session = { snapshotEvents: () => sampleEvents };\n    expect(dshSessionEvents(session)).toEqual(sampleEvents);\n    expect(readDshEvents(dshSessionEvents(session))).toEqual([\n      {\n        role: \"user\",\n        content: \"why is chatDocs zero?\",\n        timestamp: \"2026-09-05T08:00:00.000Z\",\n      },\n      {\n        role: \"assistant\",\n        content: \"session.events was removed.\",\n        timestamp: \"2026-09-05T08:00:01.000Z\",\n      },\n    ]);\n  });\n\n  it(\"falls back to the legacy events property when snapshotEvents is missing\", () => {\n    const session = { events: sampleEvents };\n    expect(dshSessionEvents(session)).toBe(sampleEvents);\n    expect(readDshEvents(dshSessionEvents(session))).toHaveLength(2);\n  });\n\n  it(\"returns an empty log when neither accessor exists (pre-fix alpha.4 breakage)\", () => {\n    const session = {};\n    expect(dshSessionEvents(session)).toEqual([]);\n    expect(readDshEvents(dshSessionEvents(session))).toEqual([]);\n  });\n\n  it(\"prefers snapshotEvents over a stale events property\", () => {\n    const session = { events: [], snapshotEvents: () => sampleEvents };\n    expect(dshSessionEvents(session)).toBe(sampleEvents);\n  });\n\n  it(\"saves only a fork's own turns, not the prefix it inherited (#5940)\", () => {\n    const childTurn = {\n      type: \"user/message\",\n      data: {\n        role: \"user\",\n        content: [{ type: \"text\", text: \"now on the fork\" }],\n        source: { kind: \"user\" },\n      },\n    };\n    const fork = { snapshotEvents: () => [...sampleEvents, childTurn], inheritedEventCount: 2 };\n    expect(readDshEvents(ownEvents(fork))).toEqual([{ role: \"user\", content: \"now on the fork\" }]);\n    // The model still sees the whole history; an unforked session saves all of it.\n    expect(dshSessionEvents(fork)).toHaveLength(3);\n    expect(ownEvents({ snapshotEvents: () => sampleEvents })).toEqual(sampleEvents);\n  });\n});\n\ndescribe(\"toDshParameters\", () => {\n  const spec = (inputSchema: ToolSpec[\"inputSchema\"]): ToolSpec => ({\n    name: \"hindsight_capture_initiative\",\n    description: \"…\",\n    inputSchema,\n    annotations: {\n      readOnlyHint: false,\n      destructiveHint: false,\n      idempotentHint: false,\n      openWorldHint: false,\n    },\n    handler: async () => ({ content: [] }),\n  });\n\n  it(\"projects the Zod raw shape onto dsh's parameter JSON Schema\", () => {\n    expect(\n      toDshParameters(\n        spec({\n          title: z.string(),\n          summary: z.string().describe(\"what and why\"),\n          relates_to_page_id: z.string().optional(),\n        })\n      )\n    ).toEqual({\n      type: \"object\",\n      properties: {\n        title: { type: \"string\" },\n        summary: { type: \"string\", description: \"what and why\" },\n        relates_to_page_id: { type: \"string\" },\n      },\n      required: [\"title\", \"summary\"],\n    });\n  });\n\n  it(\"omits `required` for a tool that takes no arguments\", () => {\n    expect(toDshParameters(spec({}))).toEqual({ type: \"object\", properties: {} });\n  });\n\n  it(\"refuses a parameter shape the projection cannot express\", () => {\n    expect(() => toDshParameters(spec({ limit: z.number() as never }))).toThrow(\n      /string parameters only/\n    );\n    // The guard must see THROUGH `.optional()`, not treat every optional as a string.\n    expect(() => toDshParameters(spec({ limit: z.number().optional() as never }))).toThrow(\n      /string parameters only/\n    );\n  });\n});\n"
    },
    {
      "path": "hindsight-integrations/coding-agents/src/core/runtime.ts",
      "content": "/**\n * Host adapter runtime for PERSISTENT-PLUGIN harnesses (opencode, opencode2, Kilo, Cline, dsh, pi,\n * Prime Agent — every host that loads us once and keeps us). It delegates SessionStart and\n * prompt behavior to the same core lifecycle as fresh-process hook harnesses; this class keeps only\n * the host-specific injection, toast, and incremental-transcript responsibilities.\n *\n * A harness adapter feeds it three normalized events and reads two values back:\n *   - seedIfCold(repoPath)          : plugin load -> cold-check auto-seed (the page preamble is\n *                                     NOT computed here; onPrompt builds it per session)\n *   - onPrompt(sessionId, prompt)   : each user turn -> recall + build this turn's injection\n *   - getInjection(sessionId)       : the text to inject into this turn's user message (or undefined)\n *   - toolSpecs()                   : the hindsight_* knowledge/recall tools to register natively\n *   - onTranscript(sessionId, turns, lastTurnComplete): full transcript -> write back (on by default)\n *   - onSessionIdle(sessionId)      : assistant finished -> refetch + write back the completed\n *                                     exchange (the Stop-equivalent these hosts lack)\n *   - flush()                       : host is exiting -> wait (bounded) for in-flight write-backs\n * No opencode/claude specifics live here — only the memory logic.\n */\nimport type { Config } from \"./config\";\nimport { maybeAutoUpdate } from \"./auto-update\";\nimport { DAEMON_WAIT_RETAIN_MS, DAEMON_WAIT_SESSION_START_MS, ensureDaemon } from \"./daemon\";\nimport { diag } from \"./diag\";\nimport { describeError, log, setLogLevel } from \"./log\";\nimport type { HindsightClient } from \"./hindsight\";\nimport { buildKnowledgePreamble } from \"./knowledge-injection\";\nimport { buildKnowledgeTools, type ToolSpec } from \"./knowledge-tools\";\nimport { buildPageTrigger } from \"./missions\";\nimport { retainLiveSession, type TransportTurn } from \"./chat\";\nimport { memoryCursorStore } from \"./retain-cursor\";\nimport { memoryUsageCursorStore, recordUsage } from \"./usage\";\nimport { buildRetainStamp } from \"./retain-stamp\";\nimport { buildSessionStartContext } from \"./session-start\";\nimport { syncCompanionSkill } from \"./skill-sync\";\nimport { buildHookOutput } from \"./hook\";\nimport { sessionCacheFile, writeSessionCache } from \"./session-cache\";\n\nconst HARNESS = \"opencode\";\n/** How long `flush` holds a host's exit for in-flight write-backs: room for one retain request. */\nconst FLUSH_TIMEOUT_MS = 10_000;\n\nexport class RuntimeCore {\n  private readonly injection = new Map<string, string>(); // sessionId -> this turn's injection block\n  private readonly turnCount = new Map<string, number>(); // sessionId -> user-turn counter (cadence)\n  private readonly sessionState = new Map<string, { startTs: string; retainedTurns: number }>();\n  /** Live write-back cursors. In memory, unlike the hook harnesses': this host outlives the session. */\n  private readonly cursors = memoryCursorStore();\n  /** Turns already written to the usage log (core/usage.ts), per session. */\n  private readonly usageCursors = memoryUsageCursorStore();\n  /** Pulls a session's CURRENT transcript from the host (set by the adapter); see onSessionIdle. */\n  private fetchTranscript?: (sessionId: string) => Promise<TransportTurn[]>;\n  /** Write-backs started and not yet settled — what `flush` waits for. */\n  private readonly inFlight = new Set<Promise<void>>();\n  private deferInitialReflect = false;\n  /** Host-notice channel (opencode/Kilo: client.tui.showToast via the adapter). Optional, fail-open. */\n  private notify?: (title: string, message: string) => void;\n\n  constructor(\n    private readonly client: HindsightClient,\n    private readonly bankId: string,\n    private readonly cfg: Config,\n    /**\n     * Which persistent-plugin host loaded us. Scopes diagnostics, the session cache file and the\n     * retained transcript's harness field, so Kilo sessions don't masquerade as opencode ones.\n     * Defaults to opencode, the original (and only other) plugin harness.\n     */\n    readonly harness: string = HARNESS,\n    /** Workspace root this host opened — the SAME directory bank resolution used, so a\n     *  `{gitProject}` in retainTags names the repo the bank was derived from. */\n    private readonly projectDir: string = process.cwd()\n  ) {\n    setLogLevel(cfg.logLevel);\n  }\n\n  setNotifier(notify: (title: string, message: string) => void): void {\n    this.notify = notify;\n  }\n\n  /**\n   * Supply a way to READ the session's transcript back from the host. Without it `onSessionIdle`\n   * no-ops, so hosts that can't refetch keep the old (lagging) turn-driven write-back rather than\n   * retaining a stale transcript.\n   */\n  setTranscriptSource(fetch: (sessionId: string) => Promise<TransportTurn[]>): void {\n    this.fetchTranscript = fetch;\n  }\n\n  /** The hindsight_* knowledge + recall tools, bound to this bank, for the harness to register natively. */\n  toolSpecs(): ToolSpec[] {\n    return buildKnowledgeTools(this.client, this.bankId, {\n      repoDir: this.projectDir,\n      harness: this.harness,\n      pageTrigger: buildPageTrigger(this.cfg),\n      reflectTimeoutMs: this.cfg.reflectToolTimeoutMs,\n      reflectBudget: this.cfg.reflectBudget,\n      toolGuideExtra: this.cfg.toolGuideExtra,\n      stampFor: () =>\n        buildRetainStamp(this.cfg, {\n          directory: this.projectDir,\n          harness: this.harness,\n          bankId: this.bankId,\n        }),\n    });\n  }\n\n  get writeBackEnabled(): boolean {\n    return this.cfg.retainSessions;\n  }\n\n  /**\n   * Plugin load (SessionStart-equivalent): on a cold repo, deterministically start the background\n   * git-log seed + codebase survey. Reuses the exact hook-harness logic\n   * (`buildSessionStartContext`) so opencode seeds identically. Never throws.\n   *\n   * It deliberately does NOT keep that call's knowledge preamble. This runs once per PROCESS and\n   * these hosts outlive every session, so a roster captured here is stale for every session but\n   * the first — `onPrompt` builds its own from the session's live page list (#4607).\n   */\n  async seedIfCold(repoPath: string | undefined): Promise<void> {\n    // Anti-recursion: a headless survey session runs the agent (which loads this plugin) with\n    // HINDSIGHT_DISABLE_HOOKS=1 — the tools stay registered (toolSpecs, so the survey can ingest),\n    // but seeding/recall/write-back must no-op or the survey would re-seed itself (see core/survey.ts).\n    if (process.env.HINDSIGHT_DISABLE_HOOKS) return;\n    // Companion skill, the same housekeeping `runSessionStartHook` does for hook harnesses — but\n    // with `install`, because a persistent-plugin host can be wired by its OWN plugin manager\n    // (`dsh plugin add …`, `cline plugin install`), a route our installer never sees, leaving the\n    // plugin loaded with its tools registered and no skill on disk at all (#4406). No-op for a host\n    // with no skills directory (opencode; opencode2 registers it in memory instead).\n    syncCompanionSkill(this.harness, { install: true });\n    // Daemon mode: this is the SessionStart of a persistent-plugin host, so it owns the same\n    // warm-up the hook harnesses do in `runSessionStartHook` — start it before the user has typed\n    // anything, wait only briefly, and let a cold one keep coming up in the background. Without it\n    // these hosts never started a daemon at all and every request failed with ECONNREFUSED (#3524);\n    // `runSessionStartHook` is a hook-only wrapper, so calling `buildSessionStartContext` directly\n    // (as every plugin harness does) skipped the ensure entirely.\n    await ensureDaemon(this.cfg, this.harness, { waitMs: DAEMON_WAIT_SESSION_START_MS });\n    // Same session-start housekeeping the hook harnesses do in `runSessionStartHook`: a persistent\n    // plugin host is a session start too, and leaving it out would mean opencode/Kilo/Cline users\n    // never got an update — the parity gap `ensureDaemon` above already had to be fixed for.\n    void maybeAutoUpdate(this.cfg);\n    try {\n      const out = await buildSessionStartContext({\n        cwd: repoPath || process.cwd(),\n        bankId: this.bankId,\n        cfg: this.cfg,\n        client: this.client,\n        harness: this.harness,\n      });\n      // The seed note is user-facing; opencode has no visible-system channel at load, so surface it\n      // on stderr (shows in the plugin log / console) rather than dropping it.\n      // Banner: via the host's toast API when available (stderr corrupts the TUI); always logged.\n      if (out.systemMessage) {\n        const plain = out.systemMessage.replace(/\\x1b\\[[0-9;]*m/g, \"\");\n        log.info(this.harness, plain);\n        this.notify?.(\"Hindsight\", plain.replace(/^Hindsight is /, \"Is \"));\n      }\n      this.deferInitialReflect = out.deferInitialReflect === true;\n    } catch {\n      /* seeding is best-effort — a cold-check failure never breaks the agent */\n    }\n  }\n\n  /**\n   * Each user turn delegates to the same `buildHookOutput` used by hook harnesses. The cache file\n   * intentionally replaces the old in-memory reflect/page state, keeping lifecycle behavior\n   * identical across hosts while this adapter retains only delivery-specific state.\n   */\n  async onPrompt(sessionId: string | undefined, prompt: string): Promise<void> {\n    if (process.env.HINDSIGHT_DISABLE_HOOKS) return; // anti-recursion (see seedIfCold)\n    if (!sessionId) return;\n    // No prompt text means no recall, so no block for this turn either: the previous turn's block\n    // must not be handed out again, since every host now persists it into the user message.\n    if (!prompt.trim()) {\n      this.injection.delete(sessionId);\n      return;\n    }\n    const turns = (this.turnCount.get(sessionId) ?? 0) + 1;\n    this.turnCount.set(sessionId, turns);\n\n    const cacheFile = sessionCacheFile(this.harness, sessionId);\n    if (this.deferInitialReflect) {\n      // `seedIfCold` has no session id. Transfer its SessionStart decision to the first concrete\n      // session here; `buildHookOutput` consumes it exactly once, like hook harnesses do.\n      this.deferInitialReflect = false;\n      writeSessionCache(cacheFile, { deferInitialReflect: true });\n    }\n    const output = await buildHookOutput({\n      harness: this.harness,\n      prompt,\n      cfg: this.cfg,\n      client: this.client,\n      cacheFile,\n    });\n\n    const blocks: string[] = [];\n    // The SessionStart-equivalent preamble, injected once on the first turn (later turns get the\n    // periodic refresh below). Built HERE, from this session's own roster, rather than reused from\n    // plugin load: that one is a process-lifetime snapshot, so a host started before the pages\n    // existed told every later session \"No knowledge pages yet\" while the same turn's memory block\n    // listed pages by id (#4607).\n    if (turns === 1) {\n      blocks.push(\n        buildKnowledgePreamble(output.pages, {\n          reflectOnNewGoals: this.cfg.autoInject !== \"reflect\",\n          extra: this.cfg.toolGuideExtra,\n        })\n      );\n    }\n    if (output.context) blocks.push(output.context);\n    // OpenCode has no user-message hook channel; use its native toast instead of stderr, which\n    // renders inside the TUI input line. The shared output owns when a notice exists.\n    if (output.notice) {\n      const preview = output.notice.replace(/\\s+/g, \" \").trim().slice(0, 140);\n      log.info(this.harness, \"reflect goal\", { preview });\n      this.notify?.(\"Hindsight · recalled past decisions\", preview);\n    }\n    const block = blocks.filter(Boolean).join(\"\\n\\n\");\n    this.injection.set(sessionId, block);\n  }\n\n  /**\n   * The text to inject into this turn's user message (built by the preceding onPrompt), or\n   * undefined.\n   *\n   * It goes into the USER turn on every host, never the system prompt (#5914). The block changes\n   * from turn to turn — the recall runs once, the roster refresh on a cadence — so a system prompt\n   * carrying it differed between requests and broke the provider's prefix cache from that point\n   * on. Persisted in the turn it belongs to, it leaves the system prompt and the earlier history\n   * byte-identical. That used to need a fallback to the most recent block for opencode's\n   * `experimental.chat.system.transform`, which fired with no session id; nothing reads it that\n   * way any more.\n   */\n  getInjection(sessionId: string): string | undefined {\n    return this.injection.get(sessionId) || undefined;\n  }\n\n  /**\n   * Full normalized transcript (rich: user/assistant text + tool calls/outputs): upsert every turn\n   * when enabled. On by default for persistent-plugin hosts (parity with hook-harness Stop\n   * write-back), so opencode sessions compound into memory; opt out with `retainSessions: false`.\n   *\n   * There is deliberately no client-side cadence. Batching write-backs meant holding turns in a\n   * process the host can close at any moment, with no reliable signal on the way out — the flush a\n   * cadence needs would have to ride a session-end hook, and those are cancelled at shutdown. The\n   * server coalesces instead: queued retains for one document fold into a single execution\n   * (`engine.retain.fold`), so submitting every turn costs one extraction, not one per turn, and\n   * nothing is ever held somewhere it can be lost.\n   */\n  async onTranscript(\n    sessionId: string,\n    turns: TransportTurn[],\n    /** Whether the agent has finished answering the last prompt. Required, not defaulted: opencode\n     *  hands this over while BUILDING a request (false), pi and Cline after the run ends (true), and\n     *  a wrong default records every turn one late and never the session's last. */\n    lastTurnComplete: boolean\n  ): Promise<void> {\n    if (process.env.HINDSIGHT_DISABLE_HOOKS) return; // anti-recursion (see seedIfCold)\n    if (!sessionId || !turns.length) return;\n    // Usage is a local file, so it is recorded whether or not write-back is on (#5391).\n    this.recordUsage(sessionId, turns, lastTurnComplete);\n    if (!this.writeBackEnabled) return;\n    const st = this.stateFor(sessionId);\n    this.retain(sessionId, turns, st.startTs);\n  }\n\n  /**\n   * Session went idle — the assistant has finished replying.\n   *\n   * This is the Stop-equivalent these hosts lack. `onTranscript` alone is driven by\n   * `messages.transform`, which the host runs while BUILDING a request, so the transcript it hands\n   * us never contains the reply that request produced: write-back always lagged one user turn, and\n   * a session's final exchange was never retained at all. Refetching here (rather than replaying a\n   * cached list) is the whole point — the cached one predates the reply.\n   *\n   * Cadence is deliberately bypassed: idle means \"there may be nothing after this\", so a pending\n   * turn must not wait for a threshold it will never reach.\n   */\n  async onSessionIdle(sessionId: string): Promise<void> {\n    if (process.env.HINDSIGHT_DISABLE_HOOKS) return; // anti-recursion (see seedIfCold)\n    if (!sessionId || !this.fetchTranscript) return;\n    let turns: TransportTurn[];\n    try {\n      turns = await this.fetchTranscript(sessionId);\n    } catch (e) {\n      diag(this.harness, \"idle_fetch_failed\", {\n        error: describeError(e),\n        session: sessionId,\n      });\n      return;\n    }\n    if (!turns.length) return;\n    this.recordUsage(sessionId, turns, true); // idle: the reply is in\n    if (!this.writeBackEnabled) return; // usage above is local and recorded regardless (#5391)\n    const st = this.stateFor(sessionId);\n    // idle can fire more than once for one exchange (and again on a session with no new activity);\n    // only retain when this transcript actually grew past what we last wrote.\n    if (turns.length <= st.retainedTurns) return;\n    st.retainedTurns = turns.length;\n    this.retain(sessionId, turns, st.startTs, \"idle\");\n  }\n\n  private recordUsage(sessionId: string, turns: TransportTurn[], lastTurnComplete: boolean): void {\n    recordUsage({\n      harness: this.harness,\n      sessionId,\n      bankId: this.bankId,\n      turns,\n      cursors: this.usageCursors,\n      lastTurnComplete,\n      // No `reviseLastTurn` here, unlike the hook path: this runtime never records a turn before its\n      // reply exists. `onTranscript` is handed `false` while the host is still building the request,\n      // which holds the turn back, and `onSessionIdle` refetches a transcript that includes the\n      // reply before recording it.\n    });\n  }\n\n  private stateFor(sessionId: string): {\n    startTs: string;\n    retainedTurns: number;\n  } {\n    let st = this.sessionState.get(sessionId);\n    if (!st) {\n      st = { startTs: new Date().toISOString(), retainedTurns: 0 };\n      this.sessionState.set(sessionId, st);\n    }\n    return st;\n  }\n\n  /**\n   * Wait for every write-back still in flight, at most `timeoutMs`. Write-backs stay fire-and-forget\n   * so a turn never blocks on the network; a host that announces its exit (pi's `session_shutdown`)\n   * calls this so the session's final retain is not dropped with the process (#5081). Bounded so a\n   * stalled server cannot hold the host's exit open. Never throws.\n   */\n  async flush(timeoutMs = FLUSH_TIMEOUT_MS): Promise<void> {\n    if (!this.inFlight.size) return;\n    let timer: ReturnType<typeof setTimeout> | undefined;\n    await Promise.race([\n      Promise.all(this.inFlight),\n      new Promise<void>((r) => {\n        timer = setTimeout(r, timeoutMs);\n      }),\n    ]);\n    clearTimeout(timer);\n  }\n\n  /** Fire-and-forget upsert of the session transcript; never throws into the host. */\n  private retain(\n    sessionId: string,\n    turns: TransportTurn[],\n    startTs: string,\n    trigger = \"turn\"\n  ): void {\n    const t0 = Date.now();\n    // Daemon mode: the write path is the last chance to get a daemon up — the Stop-hook role, for\n    // hosts that have no Stop hook. A daemon that died mid-session would otherwise take the whole\n    // exchange with it. The wait sits INSIDE the fire-and-forget chain, so\n    // unlike the Stop hook it costs the host nothing: this call already returns before the retain\n    // does. Deliberately not gated on the result — retain proceeds either way, so an unreachable\n    // daemon produces the same `retain_failed` diagnostic as an unreachable Cloud server.\n    const write = ensureDaemon(this.cfg, this.harness, { waitMs: DAEMON_WAIT_RETAIN_MS })\n      .then(() =>\n        retainLiveSession(this.client, sessionId, turns, startTs, this.harness, {\n          cursors: this.cursors,\n          stamp: buildRetainStamp(this.cfg, {\n            directory: this.projectDir,\n            harness: this.harness,\n            bankId: this.bankId,\n            sessionId,\n          }),\n        })\n      )\n      .then(() =>\n        diag(this.harness, \"retain_ok\", {\n          ms: Date.now() - t0,\n          turns: turns.length,\n          session: sessionId,\n          trigger,\n        })\n      )\n      .catch((e) =>\n        diag(this.harness, \"retain_failed\", {\n          ms: Date.now() - t0,\n          error: describeError(e),\n          session: sessionId,\n          trigger,\n        })\n      );\n    this.inFlight.add(write);\n    void write.finally(() => this.inFlight.delete(write));\n  }\n}\n"
    },
    {
      "path": "hindsight-integrations/coding-agents/src/core/config.ts",
      "content": "/**\n * ONE config file: ~/.hindsight/coding-agent.json.\n *\n * Layering, later wins per field:\n *   1. built-in defaults\n *   2. environment variables (ENV_KEYS below) — a FALLBACK for containers, CI and secret managers\n *   3. the config file's top level\n *   4. its `harnesses.<name>` section for the asking harness\n *\n * There is deliberately NO project-local config: a second, repo-carried file was both a security\n * surface (untrusted repos influencing memory behavior) and a second place to look. Per-repo bank\n * routing is `mapPathToBank`; per-agent differences are `harnesses.<name>`.\n */\nimport { readFileSync } from \"node:fs\";\nimport { homedir } from \"node:os\";\nimport { join } from \"node:path\";\nimport { DEFAULT_SEED_LIMIT } from \"./seed\";\nimport { isOptedIn, pathSection } from \"./bank\";\nimport { log } from \"./log\";\nimport {\n  DEFAULT_OBSERVATION_SCOPES,\n  DEFAULT_PAGE_SEARCH_LIMIT,\n  type ObservationScopes,\n} from \"./hindsight\";\nimport {\n  type CustomPagesConfig,\n  DEFAULT_PAGE_TRIGGER_CRON,\n  DEFAULT_RETAIN_EXTRACTION_MODE,\n  isHashedCron,\n  PAGE_NAMES,\n  type PagesConfig,\n  parseHashedCron,\n  PLUGIN_GOVERNED_BANK_FIELDS,\n  RETAIN_EXTRACTION_MODES,\n  type RetainExtractionMode,\n} from \"./missions\";\n\n/** Default config-file path: ~/.hindsight/coding-agent.json */\nexport // HINDSIGHT_CONFIG joins the two env exceptions (diag/log files): it points at THE config file,\n// for containers and test harnesses where $HOME isn't the right anchor. Still one file.\nconst CONFIG_PATH =\n  process.env.HINDSIGHT_CONFIG || join(homedir(), \".hindsight\", \"coding-agent.json\");\n\n/** Daemon-mode defaults. The port matches the old per-agent Claude Code plugin so a machine that\n *  already ran that daemon keeps using the same one. */\nexport const DEFAULT_DAEMON_PORT = 9077;\nexport const DEFAULT_DAEMON_PROFILE = \"coding-agent\";\n\n/** Incremental git-sync settings (see core/sync.ts). */\n/** The config file's shape — every field optional; omitted fields take the documented default. */\nexport interface RawConfig {\n  /** Where memory lives. All three modes speak the same HTTP API; they differ only in who runs it:\n   *   \"cloud\"       — Hindsight Cloud (the default `apiUrl`)\n   *   \"self-hosted\" — a Hindsight server you run; set `apiUrl` to it\n   *   \"daemon\"      — a local `hindsight-embed` daemon this plugin starts on demand, at\n   *                   127.0.0.1:{apiPort}. `apiUrl` is ignored in this mode.\n   * Omitted, it is inferred: \"daemon\" is never assumed, so an existing config keeps talking to\n   * whatever `apiUrl` it already names. */\n  serverMode?: \"cloud\" | \"self-hosted\" | \"daemon\";\n  apiUrl?: string; // Hindsight API base URL (default https://api.hindsight.vectorize.io — Cloud; set to http://localhost:8888 for a local server)\n  apiToken?: string; // bearer token (optional)\n  /** Daemon mode: port the local daemon listens on (default 9077).\n   *  NOT 8888 — that is the conventional port for a server you run yourself, and a daemon must\n   *  never squat on it. A healthy server already on this port is adopted rather than restarted. */\n  apiPort?: number;\n  /** Daemon mode: seconds of inactivity before the daemon exits. Unset means it never exits on\n   *  its own — `hindsight-embed`'s own default, which every other Hindsight integration also\n   *  ships. This used to default to 300 here, which made the plugin the only thing on the machine\n   *  opting a shared daemon into an auto-exit nobody asked for. There is deliberately no\n   *  stop-on-session-end either: one daemon is shared by every agent and repo on the machine, so\n   *  ending one session must not cut memory out from under another. */\n  daemonIdleTimeout?: number;\n  /** Daemon mode: `hindsight-embed` profile name, i.e. which local database is used (default\n   *  \"coding-agent\"). Separate profiles keep unrelated setups from sharing memory. */\n  daemonProfile?: string;\n  /** Daemon mode: which `hindsight-embed` release to run via uvx (default \"latest\"). */\n  embedVersion?: string;\n  /** Daemon mode: local `hindsight-embed` checkout to run instead of a published release (dev). */\n  embedPackagePath?: string;\n  bankId?: string; // EXPLICIT memory bank id — set = static bank; unset = per-repo dynamic (core/bank.ts)\n  dynamicBankId?: boolean; // force dynamic resolution even when bankId is set (default: dynamic iff no bankId)\n  bankIdTemplate?: string; // dynamic bank id format (default \"coding-agent::{gitProject}\" — harness-neutral) —\n  //   placeholders: {gitProject} {project} {harness} {channel} {user} (see core/bank.ts)\n  mapPathToBank?: Record<string, string>; // absolute path -> bank; longest prefix wins; overrides everything\n  resolveWorktrees?: boolean; // {gitProject}: worktrees share the main repo's bank (default true)\n  /** Run memory ONLY in projects that were opted in (default false: every project gets memory,\n   *  which is what makes the plugin zero-setup). With it on, an unlisted project is inert — no\n   *  bank is created, nothing is retained, no seed runs — so unrelated work leaves no trace. */\n  optInOnly?: boolean;\n  /** Directories opted in, matched as PREFIXES with `~` expanded: approving a directory approves\n   *  the repos beneath it, and each still gets its own dynamic bank. A `mapPathToBank` entry counts\n   *  as opted in too, since routing a path to a named bank already declares that project. */\n  optInPaths?: string[];\n  harness?: string; // runtime adapter (default \"opencode\")\n  disabled?: boolean; // hard off-switch — inert plugin, for a no-memory baseline (default false)\n  /** Session transcript write-back (default true; set false to opt out). Honored by every\n   *  harness: the hook harnesses' Stop write-back and the persistent plugins' per-turn\n   *  cadence alike. Gates ONLY the transcript — recall, git ingest, seeding and the memory\n   *  tools keep working (that is `disabled`'s job). */\n  retainSessions?: boolean;\n  /** Cap on concurrent retain-related requests the client sends to the API (default 10):\n   *  drain()'s per-operation polls and deepen's chat/git retain pools. A single request returning\n   *  200 while bursts get 429s means the server is rate-limiting concurrency, not total volume —\n   *  lower this rather than raising it. */\n  maxParallelRetains?: number;\n  /** Automatic session-reflect timeout (default 20000). The default, with the fallback chain after\n   *  it, fits the 30s prompt-hook timeout the installer registers on hook harnesses; going higher\n   *  there needs that host timeout raised too, or the host kills the hook mid-reflect. */\n  reflectTimeoutMs?: number;\n  /** Timeout for the agent-invoked `hindsight_reflect` tool (default 330000). Deliberately its own\n   *  knob and much larger than `reflectTimeoutMs`: that one bounds an automatic hook that must fit\n   *  the host's hook window, whereas this one bounds a call the agent made on purpose and waits on,\n   *  whose `budget: \"high\"` synthesis on a populated bank can run for minutes. The default sits\n   *  ABOVE the server's own reflect wall timeout (HINDSIGHT_API_REFLECT_WALL_TIMEOUT, 300s) so the\n   *  server decides when to give up, not an arbitrary client deadline (#3590). Unset, it inherits\n   *  an explicitly-raised `reflectTimeoutMs` — a user who raised that meant \"let reflect run\". */\n  reflectToolTimeoutMs?: number;\n  /** Retrieval timeout for autoInject \"pages\"/\"recall\" (default 7000), and the shared budget for\n   *  the page-search -> recall fallback after a reflect timeout/5xx. On hook harnesses, the full\n   *  reflect + fallback must fit the host's prompt-hook timeout (30s by default). */\n  injectTimeoutMs?: number;\n  /** Reflect budget for the `hindsight_reflect` tool: \"low\" | \"mid\" | \"high\" (default \"high\").\n   *  Drop to \"mid\"/\"low\" on a large bank where high-budget synthesis exceeds the server's wall\n   *  timeout. The automatic session-start reflect is NOT affected — it always uses \"low\" to fit\n   *  its hook window. */\n  reflectBudget?: \"low\" | \"mid\" | \"high\";\n  /** What to inject on the session's first prompt (default \"reflect\"):\n   *    \"reflect\" — one low-budget reflect synthesis (falls back to pages, then recall, on timeout/5xx)\n   *    \"pages\"   — the knowledge pages matching the prompt by search (retrieval only, no LLM)\n   *    \"recall\"  — the bank's memories recalled for the prompt (`recallOptions`; no LLM)\n   *    \"none\"    — nothing; the tool guide routes new goals through pages before optional reflection */\n  autoInject?: AutoInject;\n  /** @deprecated Use `autoInject`. Still honoured: false = `autoInject: \"none\"`, true = \"reflect\";\n   *  ignored when `autoInject` is set. Setting it logs a deprecation warning. */\n  autoReflect?: boolean;\n  /** Knowledge pages ONE search returns (default 3). Applies wherever the bank is searched: the\n   *  `autoInject: \"pages\"` injection, the reflect fallback, and the agent's\n   *  `hindsight_search_knowledge_pages` tool — the limit lives on the client so they can't drift. */\n  pageSearchLimit?: number;\n  /** Recall-request overrides, merged key-by-key into the body every recall sends (the\n   *  `autoInject: \"recall\"` source and the reflect fallback) — `{\"types\": [\"world\",\n   *  \"experience\"], \"max_tokens\": 4000}`. Keys are the API's own recall parameters, passed\n   *  through unchanged, so a parameter the API gains needs no new setting here; `query` is the\n   *  one field a config cannot replace. Defaults to `{\"types\": [\"observation\"], \"budget\": \"low\",\n   *  \"max_tokens\": 2000, \"include\": {\"entities\": null}}`.\n   *\n   *  A bank with consolidation disabled never grows observations, and the default recall comes\n   *  back empty on it: those set `{\"types\": [\"world\", \"experience\"]}`, or `{\"types\": null}` for\n   *  every type. */\n  recallOptions?: Record<string, unknown>;\n  /** Your own guidance for how the agent should treat memory, added AFTER the built-in tool guide\n   *  (SessionStart and every refresh) and after the crediting note that comes back with\n   *  `hindsight_search_knowledge_pages` results. It adds to the built-in text, never replaces it,\n   *  so the plugin's call triggers and crediting rule keep up with releases (#4791). */\n  toolGuideExtra?: string;\n  pageRefreshEveryTurns?: number; // knowledge-page refresh cadence in user turns (default 1; 0 also means 1)\n  /** What it COSTS to keep this project's knowledge pages current — the trigger stamped on every\n   *  page this plugin creates (the seeded taxonomy and each captured initiative):\n   *    \"cron\" (default)         — refresh on `pageTriggerCron` only, and only when actually stale\n   *    \"auto-refresh\"           — refresh after every consolidation that produced new material\n   *    \"manual\"                 — never refresh on its own; the tools and control plane still can\n   *  Auto-refresh is both the most current and the most expensive: one LLM synthesis per page per\n   *  consolidation, which adds up fast across auto-surveyed repos (#3506) — hence the hourly\n   *  staggered schedule as the default. Existing pages keep the trigger they were created with —\n   *  this changes what NEW pages get. */\n  pageTriggerType?: \"auto-refresh\" | \"cron\" | \"manual\";\n  /** Schedule for `pageTriggerType: \"cron\"` — UTC, standard 5-field cron, e.g. \"0 3 * * *\".\n   *  Defaults to DEFAULT_PAGE_TRIGGER_CRON (\"H * * * *\": hourly, on each page's own minute).\n   *  A field written `H` (\"0 3 * * *\" -> \"H H * * *\") is replaced per page by a value hashed from\n   *  bank + page name, so pages spread across the period instead of all firing on the one minute\n   *  this shared setting names. See `expandCronHash` in core/missions.ts. */\n  pageTriggerCron?: string;\n  /** Per-page configuration for the seeded knowledge pages, keyed by page name (case-insensitive):\n   *    \"Component map\": false                                   — don't seed this page at all\n   *    \"Key decisions and rationale\": {\"source_query\": \"...\"}   — seed it, asking your question\n   *  Omitted (the default) seeds every taxonomy page with its built-in query.\n   *\n   *  This is the supported way to own a page's query. The plugin re-syncs a page whose live query\n   *  differs from the one it is configured to have, so a query edited through the API or the\n   *  control plane is replaced on the next session (#4460); setting it here makes your wording the\n   *  configured one, and the re-sync then keeps it.\n   *\n   *  A disabled page is NOT deleted — one already seeded keeps its content and simply stops being\n   *  re-synced. The subject-scoping clause is appended to a custom query too, so a reworded page\n   *  cannot start reporting a dependency's decisions as this project's own (#3476).\n   *\n   *  File-only, like `recallOptions` — a nested object does not flatten into an env var. In a\n   *  `banks.<id>` section it REPLACES the global map rather than merging into it. */\n  pages?: PagesConfig;\n  /** Knowledge pages of your OWN, seeded alongside the taxonomy and keyed by the name they get:\n   *    \"Security posture\": {\"source_query\": \"...\", \"tags\": [\"knowledge:decision\"]}\n   *  `source_query` is the question the page answers. `tags` picks which facts feed it and is\n   *  optional — the trigger matches tags with `all`, so omitting them means no tag constraint and\n   *  the page synthesizes from everything the bank holds, rather than from nothing.\n   *\n   *  Deliberately a SEPARATE key from `pages`, not another shape inside it: `pages` rejects a name\n   *  that matches no seeded page, which is what turns a typo into a warning instead of silence. If\n   *  an unknown key there meant \"create a page\", `\"Componnet map\"` would quietly create an empty\n   *  second page instead of rewording the one that was meant.\n   *\n   *  These are re-synced like the seeded ones — the config is the source of truth for the query —\n   *  so rewording one here reaches the live page on the next session. A page you create yourself\n   *  in the control plane is a different thing entirely and is never touched.\n   *\n   *  File-only, and replaced (not merged) by a `banks.<id>` section, exactly like `pages`. */\n  customPages?: CustomPagesConfig;\n  autoSeed?: boolean; // SessionStart: auto-seed a cold repo's bank from git history (default true)\n  seedLimit?: number; // git-log document: keeps between seedLimit/2 and seedLimit newest commits (default 300)\n  codebaseSurvey?: boolean; // SessionStart: spawn a headless claude to survey a cold repo's structure (default true)\n  surveyModel?: string; // model passed to the headless survey's `claude -p --model` (default \"haiku\")\n  surveyBudgetUsd?: number; // spend cap passed to the headless survey's `claude -p --max-budget-usd` (default 2)\n  /** Plugin log verbosity (\"debug\" | \"info\" | \"warn\" | \"error\", default \"info\");\n   *  HINDSIGHT_LOG_LEVEL overrides for ad-hoc debugging. */\n  logLevel?: \"debug\" | \"info\" | \"warn\" | \"error\";\n  /** Keep the installed runtime current by itself (default true). Once a day a session start asks\n   *  npm for the published version and, when it is newer, re-stages ~/.hindsight/coding-agents in\n   *  the background — the copy every wired agent's hooks already point at. It rewires no host\n   *  config, so a release that adds a NEW hook entry point still needs a manual `install`.\n   *  Set false to pin the installed version (air-gapped machines, or a deliberate downgrade);\n   *  updating is then `npx @vectorize-io/hindsight-coding-agents install` again, as before. */\n  autoUpdate?: boolean;\n  surveyRefreshCommits?: number; // re-run the survey at SessionStart once this many commits have accrued since the last one, so structural pages track an evolving architecture (default 20; 0 = cold-seed only)\n  /** How git history feeds memory — seeding AND keeping current use the same engine:\n   *  \"message\" = commit messages only (cheap aggregated doc, re-upserted when HEAD moves);\n   *  \"full\"    = messages + every recent commit's full diff (progressive batches, newest first);\n   *  \"none\"    = git ingestion off entirely. Default \"message\" (cheap by default; opt into depth). */\n  gitIngest?: \"message\" | \"full\" | \"none\";\n  /** Extra tags stamped on every session write-back, e.g. [\"project:{gitProject}\", \"env:work\"].\n   *  Placeholders: {gitProject} {project} {harness} {bankId} {sessionId} {timestamp} {channel}\n   *  {user} (see core/retain-stamp.ts). Mainly for a SHARED bank, where the bank id no longer says\n   *  which repo a memory came from. Built-in tags win on conflict. */\n  retainTags?: string[];\n  /** Extra metadata stamped on every session write-back, e.g. {\"repo\": \"{gitProject}\"}. Same\n   *  placeholders as retainTags; built-in metadata (harness attribution) wins on conflict. */\n  retainMetadata?: Record<string, string>;\n  /** The `context` sent with every session write-back (default: DEFAULT_RETAIN_CONTEXT in\n   *  core/chat.ts, which names the user and the agent as the two speakers). Same placeholders as\n   *  retainTags. Extraction reads this to decide WHOSE claim a sentence is. */\n  retainContext?: string;\n  /** Let the plugin shape the bank's own configuration — the retain strategies it writes under,\n   *  the `knowledge` entity-label group, and (on a bank that has none) the missions (default true).\n   *\n   *  Writing is ADDITIVE: the plugin adds what the bank does not already define and never\n   *  overwrites an existing value, so an edit made in the control plane survives (#3927) — except\n   *  the extraction mode of its own strategies, which follows `retainExtractionMode`. Set false\n   *  to keep it out of the bank's configuration entirely — for a bank you shape yourself, or share\n   *  with non-coding work. That bank should then define the strategies this plugin retains under\n   *  (`git`, `gitlog`, `conversation`, `document`, `survey`): the server does not reject a retain\n   *  naming a strategy the bank lacks, it logs a warning and extracts with the bank's own config\n   *  instead — so a diff, a transcript and a survey marker all get the same generic treatment.\n   *  Knowledge pages are seeded either way (see `pageTriggerType`). */\n  manageBankConfig?: boolean;\n  /** How the server extracts memories from what this plugin retains — sessions, commits, documents\n   *  (default \"concise\"). One of \"concise\", \"verbose\", \"verbatim\", \"chunks\" (store the text with no\n   *  extraction). Every Stop writes the session back, so this is what each turn costs: \"verbose\"\n   *  extracts more detail at several times the tokens. Kept in sync on the plugin's own retain\n   *  strategies on every session start, so changing it reaches an existing bank too (unless\n   *  `manageBankConfig` is false). Anything else falls back to the default. */\n  retainExtractionMode?: RetainExtractionMode;\n  /** Bank-config fields of your own for the banks this plugin shapes, e.g.\n   *    {\"enable_observations\": false, \"enable_auto_consolidation\": false,\n   *     \"mental_model_min_refresh_interval_seconds\": 21600}\n   *  Keys are the bank-config API's own field names, passed straight through, so anything the\n   *  bank-config accepts is settable here. Written under the same rule as the rest of the\n   *  template — only where the bank does not already define the field — so a bank the plugin\n   *  creates is born with these instead of the server's defaults, while a value you set in the\n   *  control plane is never overwritten (#4725). Wins over the template on a key both name\n   *  (`enable_observations`). The fields the plugin governs itself (`retain_strategies`,\n   *  `entity_labels`, `retain_extraction_mode`) are refused with a warning: the first two are\n   *  merged per entry, the last follows `retainExtractionMode`. Ignored when `manageBankConfig`\n   *  is false.\n   *\n   *  File-only, like `recallOptions` — a nested object does not flatten into an env var. In a\n   *  `banks.<id>` section it REPLACES the global map rather than merging into it. */\n  defaultBankConfig?: Record<string, unknown>;\n  /** How consolidation groups the observations this plugin's memories feed (default \"shared\" — one\n   *  global scope per bank, so every agent working a repo builds ONE set of beliefs; see\n   *  DEFAULT_OBSERVATION_SCOPES). \"combined\" restores the server default of one scope per distinct\n   *  tag set, \"per_tag\" one per tag, \"all_combinations\" one per subset; a string[][] declares the\n   *  scopes literally. Anything else falls back to the default. */\n  observationScopes?: ObservationScopes;\n  /** Per-harness overrides of any of the fields above, keyed by harness name (\"opencode\",\n   *  \"claude-code\", ...). Lets one config file give each agent its own bank/settings. */\n  harnesses?: Record<string, Omit<RawConfig, \"harnesses\">>;\n  /** Per-BANK overrides, applied AFTER bank resolution — the per-repo opt-in/out surface, keyed\n   *  by the RESOLVED bank id (run a session once or check the banner to see it). Any behavioral\n   *  field, plus `bank` to RENAME the destination (single hop: the section is selected by the\n   *  resolved id, the rename is literal — several ids may converge on one shared bank).\n   *  Bank-resolution fields (bankId/template/map/...) are ignored here. Example:\n   *    \"banks\": { \"coding-agent::secret-client\": { \"disabled\": true },\n   *               \"coding-agent::old-name\": { \"bank\": \"team::shared\" },\n   *               \"coding-agent::big-mono\": { \"gitIngest\": \"full\", \"retainSessions\": false } } */\n  banks?: Record<string, Omit<RawConfig, \"banks\" | \"harnesses\"> & { bank?: string }>;\n  /** Per-DIRECTORY overrides, keyed by absolute path prefix (`~` allowed; longest prefix wins;\n   *  a linked worktree uses its main checkout's entry). Applied after bank resolution and before\n   *  the `banks.<id>` section, so one entry can send every repo under a directory to another\n   *  server or tenant while each repo keeps its own bank. Bank-resolution fields are ignored here,\n   *  as in `banks`. Example:\n   *    \"paths\": { \"~/work/client-x\": { \"apiToken\": \"client-x-key\" } } */\n  paths?: Record<string, Omit<RawConfig, \"banks\" | \"harnesses\" | \"paths\">>;\n}\n\n/** Fully-resolved config: every field present. */\nexport interface Config {\n  serverMode: \"cloud\" | \"self-hosted\" | \"daemon\";\n  /** The EFFECTIVE base URL. In daemon mode this is already 127.0.0.1:{apiPort}, so every caller\n   *  that builds a client keeps working without knowing which mode is active. */\n  apiUrl: string;\n  apiToken?: string;\n  apiPort: number;\n  /** Undefined = never told the daemon to auto-exit; see RawConfig above. */\n  daemonIdleTimeout?: number;\n  daemonProfile: string;\n  embedVersion?: string;\n  embedPackagePath?: string;\n  bankId?: string; // resolved per-directory via deriveBankIdOrSkip — see core/bank.ts\n  dynamicBankId?: boolean;\n  bankIdTemplate?: string;\n  mapPathToBank?: Record<string, string>;\n  resolveWorktrees?: boolean;\n  optInOnly: boolean;\n  optInPaths: string[];\n  harness: string;\n  disabled: boolean;\n  retainSessions: boolean;\n  maxParallelRetains: number;\n  reflectTimeoutMs: number;\n  reflectToolTimeoutMs: number;\n  injectTimeoutMs: number;\n  reflectBudget: \"low\" | \"mid\" | \"high\";\n  autoInject: AutoInject;\n  pageSearchLimit: number;\n  recallOptions: Record<string, unknown>;\n  toolGuideExtra?: string;\n  pageRefreshEveryTurns: number;\n  pageTriggerType: \"auto-refresh\" | \"cron\" | \"manual\";\n  pageTriggerCron?: string;\n  pages: PagesConfig;\n  customPages: CustomPagesConfig;\n  autoSeed: boolean;\n  seedLimit: number;\n  codebaseSurvey: boolean;\n  surveyModel: string;\n  surveyBudgetUsd: number;\n  surveyRefreshCommits: number;\n  gitIngest: \"message\" | \"full\" | \"none\";\n  retainTags: string[];\n  retainMetadata: Record<string, string>;\n  retainContext?: string;\n  manageBankConfig: boolean;\n  retainExtractionMode: RetainExtractionMode;\n  defaultBankConfig: Record<string, unknown>;\n  observationScopes: ObservationScopes;\n  banks: Record<string, Omit<RawConfig, \"banks\" | \"harnesses\"> & { bank?: string }>;\n  paths: Record<string, Omit<RawConfig, \"banks\" | \"harnesses\" | \"paths\">>;\n  logLevel: \"debug\" | \"info\" | \"warn\" | \"error\";\n  autoUpdate: boolean;\n}\n\n/**\n * The page-refresh trigger a raw config asks for: the schedule kind, and the expression it fires on.\n *\n * `\"cron\"` is the default and needs no `pageTriggerCron`: an omitted expression takes\n * DEFAULT_PAGE_TRIGGER_CRON, so the common config — none of these fields at all — is an hourly\n * staggered refresh. A user who wants pages to stop refreshing on their own writes \"manual\".\n *\n * A malformed `H` is refused here and not one step later: `expandCronHash` leaves an expression it\n * cannot read alone, so an unchecked `\"H(9-3) * * * *\"` would reach the server verbatim and fail\n * page creation with a cron parse error naming syntax this package invented. Such an expression\n * takes the default schedule, with a warning — the same as writing none. Ordinary cron syntax\n * stays unvalidated: the server owns that, and duplicating its parser here would only disagree\n * with it.\n */\nfunction resolvePageTrigger(raw: RawConfig): {\n  type: \"auto-refresh\" | \"cron\" | \"manual\";\n  cron?: string;\n} {\n  if (raw.pageTriggerType === \"manual\") return { type: \"manual\" };\n  if (raw.pageTriggerType === \"auto-refresh\") return { type: \"auto-refresh\" };\n  if (raw.pageTriggerType !== undefined && raw.pageTriggerType !== \"cron\")\n    log.warn(\n      \"config\",\n      `ignoring pageTriggerType=${JSON.stringify(raw.pageTriggerType)} — ` +\n        \"expected cron|auto-refresh|manual\"\n    );\n  const cron = raw.pageTriggerCron?.trim();\n  if (!cron) return { type: \"cron\", cron: DEFAULT_PAGE_TRIGGER_CRON };\n  if (!isHashedCron(cron) || parseHashedCron(cron)) return { type: \"cron\", cron };\n  log.warn(\n    \"config\",\n    `pageTriggerCron ${JSON.stringify(cron)} has a malformed hashed field — ` +\n      'write `H` or `H(<lo>-<hi>)` within the field\\'s own range, e.g. \"H H(0-5) * * *\" — ' +\n      `falling back to ${JSON.stringify(DEFAULT_PAGE_TRIGGER_CRON)}`\n  );\n  return { type: \"cron\", cron: DEFAULT_PAGE_TRIGGER_CRON };\n}\n\n/**\n * Validate `pages`, dropping anything unusable with a warning.\n *\n * A key matching no seeded page is the mistake worth catching loudly: it reads as having disabled\n * or reworded something and silently does nothing, so the warning names it alongside the set that\n * would have worked. Values are checked for the same reason — `{\"source_query\": 5}` would\n * otherwise travel and become a page whose description is `5`.\n */\nfunction resolvePages(raw: RawConfig[\"pages\"]): PagesConfig {\n  // Widened deliberately: this arrives from a hand-edited JSON file, so the declared type says\n  // what is meant, not what is there.\n  const value: unknown = raw;\n  if (!value || typeof value !== \"object\" || Array.isArray(value)) return {};\n  const out: PagesConfig = {};\n  for (const [name, entry] of Object.entries(value as Record<string, unknown>)) {\n    if (!PAGE_NAMES.some((known) => known.toLowerCase() === name.trim().toLowerCase())) {\n      log.warn(\n        \"config\",\n        `ignoring pages[${JSON.stringify(name)}] — no seeded page has that name; ` +\n          `expected one of: ${PAGE_NAMES.join(\", \")}`\n      );\n      continue;\n    }\n    if (entry === false) {\n      out[name] = false;\n      continue;\n    }\n    const query: unknown =\n      entry && typeof entry === \"object\" && !Array.isArray(entry)\n        ? (entry as { source_query?: unknown }).source_query\n        : undefined;\n    if (typeof query === \"string\" && query.trim()) {\n      out[name] = { source_query: query };\n      continue;\n    }\n    log.warn(\n      \"config\",\n      `ignoring pages[${JSON.stringify(name)}]=${JSON.stringify(entry)} — ` +\n        'expected false, or {\"source_query\": \"<your question>\"}'\n    );\n  }\n  return out;\n}\n\n/**\n * Validate `customPages` — the pages a user defines, as opposed to the taxonomy that `pages` reworks.\n *\n * A name colliding with a seeded page is refused rather than merged: the two keys mean different\n * things (rework the plugin's page vs. create your own), and picking one for the user would be a\n * guess. `tags` is optional and an absent one is not an empty page — see CustomPage.\n */\nfunction resolveCustomPages(raw: RawConfig[\"customPages\"]): CustomPagesConfig {\n  // Widened deliberately, like resolvePages: a hand-edited JSON file says what is meant, not what\n  // is there.\n  const value: unknown = raw;\n  if (!value || typeof value !== \"object\" || Array.isArray(value)) return {};\n  const out: CustomPagesConfig = {};\n  for (const [rawName, entry] of Object.entries(value as Record<string, unknown>)) {\n    const name = rawName.trim();\n    if (!name) continue;\n    if (PAGE_NAMES.some((known) => known.toLowerCase() === name.toLowerCase())) {\n      log.warn(\n        \"config\",\n        `ignoring customPages[${JSON.stringify(rawName)}] — that is a seeded page; ` +\n          \"reword it under `pages` instead\"\n      );\n      continue;\n    }\n    const query: unknown =\n      entry && typeof entry === \"object\" && !Array.isArray(entry)\n        ? (entry as { source_query?: unknown }).source_query\n        : undefined;\n    if (typeof query !== \"string\" || !query.trim()) {\n      log.warn(\n        \"config\",\n        `ignoring customPages[${JSON.stringify(rawName)}]=${JSON.stringify(entry)} — ` +\n          'expected {\"source_query\": \"<your question>\"}'\n      );\n      continue;\n    }\n    const rawTags: unknown = (entry as { tags?: unknown }).tags;\n    // A stray number or nested object would reach the API as a tag and fail page creation.\n    const tags = Array.isArray(rawTags)\n      ? rawTags.filter((t): t is string => typeof t === \"string\" && t.trim() !== \"\")\n      : [];\n    out[name] = tags.length ? { source_query: query, tags } : { source_query: query };\n  }\n  return out;\n}\n\n/** Default timeout for the automatic hook reflect — see RawConfig.reflectTimeoutMs. */\nexport const DEFAULT_REFLECT_TIMEOUT_MS = 20_000;\n/** Default timeout for the agent-invoked `hindsight_reflect` tool — see RawConfig.reflectToolTimeoutMs. */\nexport const DEFAULT_REFLECT_TOOL_TIMEOUT_MS = 330_000;\n/** Default retrieval budget for automatic injection — see RawConfig.injectTimeoutMs. */\nexport const DEFAULT_INJECT_TIMEOUT_MS = 7_000;\n\nconst REFLECT_BUDGETS = [\"low\", \"mid\", \"high\"] as const;\n\n/**\n * Which reflect budget the `hindsight_reflect` tool should ask for.\n *\n * An unrecognized value takes the default rather than travelling: the API rejects an unknown budget\n * outright, which would turn a typo here into a hard tool failure on every call.\n */\nfunction resolveReflectBudget(raw: RawConfig): \"low\" | \"mid\" | \"high\" {\n  const value: unknown = raw.reflectBudget;\n  if (value === undefined) return \"high\";\n  if (typeof value === \"string\" && (REFLECT_BUDGETS as readonly string[]).includes(value))\n    return value as \"low\" | \"mid\" | \"high\";\n  log.warn(\"config\", `ignoring reflectBudget=${JSON.stringify(value)} — expected low|mid|high`);\n  return \"high\";\n}\n\n/** The server's scalar scoping modes; anything else in this field has to be an explicit scope list. */\n// `per_source` is this plugin's own mode, resolved per document in `resolveRetainScopes` and never\n// sent to the server; the rest are the server's.\nconst OBSERVATION_SCOPE_MODES = [\n  \"shared\",\n  \"combined\",\n  \"per_tag\",\n  \"all_combinations\",\n  \"per_source\",\n] as const;\n\n/**\n * Validate `observationScopes`, falling back to the default on anything unrecognized.\n *\n * A typo here would otherwise reach the API as an unknown scoping mode and change how a whole\n * bank's observations are grouped, so an unusable value takes the default rather than travelling.\n * An empty list is unusable too, and specifically so: `[]` declares ZERO scopes, which the server\n * reads as \"no spec\" and silently treats as `combined` — the opposite of what writing this field\n * at all was meant to express.\n */\nfunction resolveObservationScopes(raw: RawConfig[\"observationScopes\"]): ObservationScopes {\n  // Widened deliberately: this arrives from a hand-edited JSON file, so the declared type says what\n  // is meant, not what is there.\n  const value: unknown = raw;\n  if (typeof value === \"string\")\n    return (OBSERVATION_SCOPE_MODES as readonly string[]).includes(value)\n      ? (value as ObservationScopes)\n      : DEFAULT_OBSERVATION_SCOPES;\n  if (Array.isArray(value)) {\n    const scopes = (value as unknown[])\n      .filter((scope): scope is unknown[] => Array.isArray(scope))\n      .map((scope) => scope.filter((t): t is string => typeof t === \"string\" && t.trim() !== \"\"));\n    if (scopes.length) return scopes;\n  }\n  return DEFAULT_OBSERVATION_SCOPES;\n}\n\n/**\n * Validate `defaultBankConfig`: an object, minus the fields the plugin governs itself.\n *\n * Same shape rule as `recallOptions` — an array would spread into numeric keys and reach the\n * import as garbage, so anything but a plain object contributes nothing. A governed key is dropped\n * here, with a warning naming the setting that owns it, rather than silently in the manifest: a\n * user who wrote `retain_strategies` there would otherwise watch it do nothing every session.\n */\nfunction resolveDefaultBankConfig(raw: RawConfig[\"defaultBankConfig\"]): Record<string, unknown> {\n  const value: unknown = raw;\n  if (!value || typeof value !== \"object\" || Array.isArray(value)) return {};\n  const out: Record<string, unknown> = {};\n  for (const [key, v] of Object.entries(value as Record<string, unknown>)) {\n    if (PLUGIN_GOVERNED_BANK_FIELDS.includes(key)) {\n      log.warn(\n        \"config\",\n        `ignoring defaultBankConfig.${key} — the plugin manages this field itself` +\n          (key === \"retain_extraction_mode\" ? \" (set retainExtractionMode instead)\" : \"\")\n      );\n      continue;\n    }\n    out[key] = v;\n  }\n  return out;\n}\n\n/** Apply defaults to a raw (file) config. Pure — the single place the defaults live. */\nexport type AutoInject = \"reflect\" | \"pages\" | \"recall\" | \"none\";\nconst AUTO_INJECT_MODES: readonly AutoInject[] = [\"reflect\", \"pages\", \"recall\", \"none\"];\n\n/** `autoInject` wins; otherwise the deprecated `autoReflect: false` means \"none\". */\nfunction resolveAutoInject(raw: RawConfig): AutoInject {\n  if (raw.autoReflect !== undefined) {\n    const replacement = raw.autoReflect === false ? \"none\" : \"reflect\";\n    log.warn(\"config\", `autoReflect is deprecated — use autoInject: \"${replacement}\" instead`);\n  }\n  if (AUTO_INJECT_MODES.includes(raw.autoInject as AutoInject)) return raw.autoInject as AutoInject;\n  return raw.autoReflect === false ? \"none\" : \"reflect\";\n}\n\nexport function resolveConfig(raw: RawConfig = {}): Config {\n  const serverMode = [\"cloud\", \"self-hosted\", \"daemon\"].includes(raw.serverMode as string)\n    ? (raw.serverMode as \"cloud\" | \"self-hosted\" | \"daemon\")\n    : \"cloud\";\n  const apiPort = raw.apiPort || DEFAULT_DAEMON_PORT;\n  const pageTrigger = resolvePageTrigger(raw);\n  return {\n    serverMode,\n    // Daemon mode resolves the URL HERE rather than at each call site: every entry point already\n    // builds its client from cfg.apiUrl, so collapsing the mode into that one field means the\n    // daemon needs no plumbing through eight separate constructors.\n    apiUrl:\n      serverMode === \"daemon\"\n        ? `http://127.0.0.1:${apiPort}`\n        : (raw.apiUrl ?? \"https://api.hindsight.vectorize.io\"),\n    apiToken: raw.apiToken || undefined,\n    apiPort,\n    daemonIdleTimeout: raw.daemonIdleTimeout,\n    daemonProfile: raw.daemonProfile || DEFAULT_DAEMON_PROFILE,\n    embedVersion: raw.embedVersion || undefined,\n    embedPackagePath: raw.embedPackagePath || undefined,\n    bankId: raw.bankId,\n    dynamicBankId: raw.dynamicBankId,\n    bankIdTemplate: raw.bankIdTemplate,\n    mapPathToBank: raw.mapPathToBank,\n    resolveWorktrees: raw.resolveWorktrees,\n    optInOnly: raw.optInOnly ?? false,\n    // Same shape as retainTags: a config typo must not become a path that silently approves nothing.\n    optInPaths: Array.isArray(raw.optInPaths)\n      ? raw.optInPaths.filter((p): p is string => typeof p === \"string\" && p.trim() !== \"\")\n      : [],\n    harness: raw.harness ?? \"opencode\",\n    disabled: raw.disabled ?? false,\n    retainSessions: raw.retainSessions ?? true, // write sessions back by default, every harness\n    manageBankConfig: raw.manageBankConfig ?? true,\n    retainExtractionMode: RETAIN_EXTRACTION_MODES.includes(raw.retainExtractionMode!)\n      ? raw.retainExtractionMode!\n      : DEFAULT_RETAIN_EXTRACTION_MODE,\n    defaultBankConfig: resolveDefaultBankConfig(raw.defaultBankConfig),\n    maxParallelRetains: raw.maxParallelRetains || 10,\n    reflectTimeoutMs: raw.reflectTimeoutMs || DEFAULT_REFLECT_TIMEOUT_MS,\n    // Inherit an explicitly-raised reflectTimeoutMs (that is what users reaching for a longer\n    // reflect already set), but never let it LOWER the tool below the default — a short window is\n    // set to bound the automatic hook, not to cut off a call the agent is waiting on.\n    reflectToolTimeoutMs:\n      raw.reflectToolTimeoutMs ||\n      Math.max(raw.reflectTimeoutMs || 0, DEFAULT_REFLECT_TOOL_TIMEOUT_MS),\n    injectTimeoutMs: raw.injectTimeoutMs || DEFAULT_INJECT_TIMEOUT_MS,\n    reflectBudget: resolveReflectBudget(raw),\n    autoInject: resolveAutoInject(raw),\n    pageSearchLimit: raw.pageSearchLimit || DEFAULT_PAGE_SEARCH_LIMIT,\n    // Same shape as retainMetadata: an object, or nothing. An array would spread into numeric\n    // keys and reach the API as garbage, so it is rejected like any other non-object.\n    recallOptions:\n      raw.recallOptions &&\n      typeof raw.recallOptions === \"object\" &&\n      !Array.isArray(raw.recallOptions)\n        ? { ...raw.recallOptions }\n        : {},\n    toolGuideExtra:\n      typeof raw.toolGuideExtra === \"string\" && raw.toolGuideExtra.trim()\n        ? raw.toolGuideExtra\n        : undefined,\n    // Every turn, not every tenth. The guide is what tells the agent WHEN to reach for memory, and\n    // at a cadence of 10 a normal session is told once, on turn 1, and never again. Measured over\n    // 40 real Claude Code turns, moving this from 10 to 1 took searches from 15% of turns to 32.5%\n    // with no wording change at all. The cost is the guide's ~2KB re-sent per turn, which caches.\n    pageRefreshEveryTurns: raw.pageRefreshEveryTurns || 1,\n    pageTriggerType: pageTrigger.type,\n    pageTriggerCron: pageTrigger.cron,\n    pages: resolvePages(raw.pages),\n    customPages: resolveCustomPages(raw.customPages),\n    autoSeed: raw.autoSeed ?? true,\n    seedLimit: raw.seedLimit || DEFAULT_SEED_LIMIT,\n    codebaseSurvey: raw.codebaseSurvey ?? true,\n    surveyModel: raw.surveyModel || \"haiku\",\n    surveyBudgetUsd: raw.surveyBudgetUsd || 2,\n    surveyRefreshCommits: raw.surveyRefreshCommits ?? 20,\n    gitIngest: [\"message\", \"full\", \"none\"].includes(raw.gitIngest as string)\n      ? (raw.gitIngest as \"message\" | \"full\" | \"none\")\n      : \"message\",\n    // Hostile input is a config typo, not an attack: keep only string entries so a stray number or\n    // nested object cannot reach the API as a tag and fail the whole retain.\n    retainTags: Array.isArray(raw.retainTags)\n      ? raw.retainTags.filter((t): t is string => typeof t === \"string\" && t.trim() !== \"\")\n      : [],\n    // Undefined, not \"\", when unset or blank: the retain call distinguishes \"not configured\" (use\n    // the built-in default) from a configured value, and an empty context would strip the default.\n    retainContext:\n      typeof raw.retainContext === \"string\" && raw.retainContext.trim() !== \"\"\n        ? raw.retainContext\n        : undefined,\n    retainMetadata:\n      raw.retainMetadata && typeof raw.retainMetadata === \"object\"\n        ? Object.fromEntries(\n            Object.entries(raw.retainMetadata).filter(([, v]) => typeof v === \"string\")\n          )\n        : {},\n    observationScopes: resolveObservationScopes(raw.observationScopes),\n    banks: raw.banks && typeof raw.banks === \"object\" ? raw.banks : {},\n    paths: raw.paths && typeof raw.paths === \"object\" ? raw.paths : {},\n    logLevel: [\"debug\", \"info\", \"warn\", \"error\"].includes(raw.logLevel as string)\n      ? (raw.logLevel as \"debug\" | \"info\" | \"warn\" | \"error\")\n      : \"info\",\n    autoUpdate: raw.autoUpdate ?? true,\n  };\n}\n\nfunction readRaw(path: string): RawConfig {\n  try {\n    return JSON.parse(readFileSync(path, \"utf8\")) as RawConfig;\n  } catch (e) {\n    if ((e as NodeJS.ErrnoException)?.code !== \"ENOENT\") {\n      console.error(`hindsight: ignoring invalid config at ${path}: ${(e as Error)?.message || e}`);\n    }\n    return {};\n  }\n}\n\n/** Shallow-merge b over a; `harnesses` never survives into a layer; `banks` merges by bank id and\n *  `paths` by prefix. */\nfunction mergeRaw(a: RawConfig, b: RawConfig): RawConfig {\n  const { harnesses: _drop, ...flat } = b;\n  return {\n    ...a,\n    ...flat,\n    banks: { ...(a.banks ?? {}), ...(b.banks ?? {}) },\n    paths: { ...(a.paths ?? {}), ...(b.paths ?? {}) },\n  };\n}\n\n/**\n * Keys a PROJECT-LOCAL (untrusted, repo-supplied) config may NOT set. These control where the user's\n * credential + prompts/transcripts are sent (`apiUrl`, `apiToken`) or remap banks globally\n * (`mapPathToBank`, which \"overrides everything\"). A repo can still set its own per-repo bank via\n * `bankId`/`bankIdTemplate` — just not the network endpoint, token, or global path→bank map. The\n * user-global config is trusted and unrestricted.\n */\nexport interface LoadOptions {\n  /** Which harness is asking (\"opencode\", \"claude-code\", ...) — applies its `harnesses.<name>` overrides. */\n  harness?: string;\n  /** Explicit global-config path (default ~/.hindsight/coding-agent.json). */\n  path?: string;\n}\n\n/** Apply one config layer (its top level, then its `harnesses.<name>` override) over `raw`. */\nfunction applyLayer(raw: RawConfig, layer: RawConfig, harness?: string): RawConfig {\n  let out = mergeRaw(raw, layer);\n  const perHarness = harness ? layer.harnesses?.[harness] : undefined;\n  if (perHarness) out = mergeRaw(out, perHarness);\n  return out;\n}\n\n/**\n * Env var backing each scalar setting: `HINDSIGHT_` + the field in SCREAMING_SNAKE.\n *\n * These are a FALLBACK, not an override — the config file still wins wherever it sets a value, so\n * an existing file behaves exactly as before. They exist for the places a file is awkward:\n * containers, CI, and secret managers that inject `HINDSIGHT_API_TOKEN` rather than writing a\n * credential to disk.\n *\n * The map-valued settings (mapPathToBank, harnesses, banks, retainMetadata, recallOptions, pages,\n * customPages, defaultBankConfig) are deliberately\n * absent: they are structures whose whole point is per-repo/per-harness/per-key branching, which\n * does not survive flattening into one env var. They stay file-only.\n */\nconst ENV_KEYS = {\n  serverMode: \"HINDSIGHT_SERVER_MODE\",\n  apiUrl: \"HINDSIGHT_API_URL\",\n  apiToken: \"HINDSIGHT_API_TOKEN\",\n  // These four keep the names the old per-agent Claude Code plugin used, so a user migrating from\n  // it can carry their existing environment over unchanged.\n  apiPort: \"HINDSIGHT_API_PORT\",\n  daemonIdleTimeout: \"HINDSIGHT_DAEMON_IDLE_TIMEOUT\",\n  embedVersion: \"HINDSIGHT_EMBED_VERSION\",\n  embedPackagePath: \"HINDSIGHT_EMBED_PACKAGE_PATH\",\n  daemonProfile: \"HINDSIGHT_DAEMON_PROFILE\",\n  bankId: \"HINDSIGHT_BANK_ID\",\n  dynamicBankId: \"HINDSIGHT_DYNAMIC_BANK_ID\",\n  bankIdTemplate: \"HINDSIGHT_BANK_ID_TEMPLATE\",\n  resolveWorktrees: \"HINDSIGHT_RESOLVE_WORKTREES\",\n  optInOnly: \"HINDSIGHT_OPT_IN_ONLY\",\n  optInPaths: \"HINDSIGHT_OPT_IN_PATHS\",\n  harness: \"HINDSIGHT_HARNESS\",\n  disabled: \"HINDSIGHT_DISABLED\",\n  retainSessions: \"HINDSIGHT_RETAIN_SESSIONS\",\n  maxParallelRetains: \"HINDSIGHT_MAX_PARALLEL_RETAINS\",\n  reflectTimeoutMs: \"HINDSIGHT_REFLECT_TIMEOUT_MS\",\n  reflectToolTimeoutMs: \"HINDSIGHT_REFLECT_TOOL_TIMEOUT_MS\",\n  injectTimeoutMs: \"HINDSIGHT_INJECT_TIMEOUT_MS\",\n  reflectBudget: \"HINDSIGHT_REFLECT_BUDGET\",\n  autoInject: \"HINDSIGHT_AUTO_INJECT\",\n  pageSearchLimit: \"HINDSIGHT_PAGE_SEARCH_LIMIT\",\n  toolGuideExtra: \"HINDSIGHT_TOOL_GUIDE_EXTRA\",\n  autoReflect: \"HINDSIGHT_AUTO_REFLECT\",\n  pageRefreshEveryTurns: \"HINDSIGHT_PAGE_REFRESH_EVERY_TURNS\",\n  pageTriggerType: \"HINDSIGHT_PAGE_TRIGGER_TYPE\",\n  pageTriggerCron: \"HINDSIGHT_PAGE_TRIGGER_CRON\",\n  autoSeed: \"HINDSIGHT_AUTO_SEED\",\n  seedLimit: \"HINDSIGHT_SEED_LIMIT\",\n  codebaseSurvey: \"HINDSIGHT_CODEBASE_SURVEY\",\n  surveyModel: \"HINDSIGHT_SURVEY_MODEL\",\n  surveyBudgetUsd: \"HINDSIGHT_SURVEY_BUDGET_USD\",\n  surveyRefreshCommits: \"HINDSIGHT_SURVEY_REFRESH_COMMITS\",\n  logLevel: \"HINDSIGHT_LOG_LEVEL\",\n  autoUpdate: \"HINDSIGHT_AUTO_UPDATE\",\n  gitIngest: \"HINDSIGHT_GIT_INGEST\",\n  // Scalar modes only (\"shared\", \"combined\", \"per_tag\", \"all_combinations\"). An explicit scope\n  // list is a list OF lists, which does not survive flattening into one variable — file-only.\n  observationScopes: \"HINDSIGHT_OBSERVATION_SCOPES\",\n  // Comma-separated, e.g. HINDSIGHT_RETAIN_TAGS=\"project:{gitProject},env:work\". A LIST rather than\n  // a map, so it flattens cleanly; its sibling retainMetadata stays file-only for the reason above.\n  retainTags: \"HINDSIGHT_RETAIN_TAGS\",\n  manageBankConfig: \"HINDSIGHT_MANAGE_BANK_CONFIG\",\n  retainExtractionMode: \"HINDSIGHT_RETAIN_EXTRACTION_MODE\",\n} as const satisfies Partial<Record<keyof RawConfig, string>>;\n\n/** Fields parsed as booleans/numbers/comma-separated lists; everything else is taken as a string. */\nconst ENV_BOOLEANS = new Set<keyof RawConfig>([\n  \"dynamicBankId\",\n  \"resolveWorktrees\",\n  \"optInOnly\",\n  \"disabled\",\n  \"retainSessions\",\n  \"autoReflect\",\n  \"autoSeed\",\n  \"codebaseSurvey\",\n  \"autoUpdate\",\n  \"manageBankConfig\",\n]);\nconst ENV_LISTS = new Set<keyof RawConfig>([\"retainTags\", \"optInPaths\"]);\nconst ENV_NUMBERS = new Set<keyof RawConfig>([\n  \"apiPort\",\n  \"daemonIdleTimeout\",\n  \"maxParallelRetains\",\n  \"reflectTimeoutMs\",\n  \"reflectToolTimeoutMs\",\n  \"injectTimeoutMs\",\n  \"pageSearchLimit\",\n  \"pageRefreshEveryTurns\",\n  \"seedLimit\",\n  \"surveyBudgetUsd\",\n  \"surveyRefreshCommits\",\n]);\n\n/**\n * Read the env fallback layer. An unset or empty var contributes nothing (so it can't mask a file\n * value), and a malformed number is ignored with a warning rather than silently becoming NaN —\n * which would otherwise disable a timeout or cadence in a way that is very hard to trace.\n */\nexport function readEnvConfig(env: NodeJS.ProcessEnv = process.env): RawConfig {\n  const out: Record<string, unknown> = {};\n  for (const [key, name] of Object.entries(ENV_KEYS) as [keyof RawConfig, string][]) {\n    const value = env[name];\n    if (value === undefined || value.trim() === \"\") continue;\n    if (ENV_BOOLEANS.has(key)) {\n      out[key] = [\"1\", \"true\", \"yes\", \"on\"].includes(value.trim().toLowerCase());\n    } else if (ENV_LISTS.has(key)) {\n      // Empty entries dropped, so a trailing comma or \"a,,b\" is a typo rather than an empty tag.\n      const items = value\n        .split(\",\")\n        .map((v) => v.trim())\n        .filter(Boolean);\n      if (items.length) out[key] = items;\n    } else if (ENV_NUMBERS.has(key)) {\n      const n = Number(value);\n      if (Number.isFinite(n)) out[key] = n;\n      else console.error(`hindsight: ignoring ${name}=${value} — not a number`);\n    } else {\n      out[key] = value;\n    }\n  }\n  return out as RawConfig;\n}\n\n/** Load + resolve config from THE config file, with env as a fallback. Missing file -> defaults. */\nexport function loadConfig(opts: LoadOptions | string = {}): Config {\n  const o: LoadOptions = typeof opts === \"string\" ? { path: opts } : opts; // legacy: loadConfig(path)\n  // Env first so the FILE wins on any field it sets.\n  const withEnv = applyLayer({}, readEnvConfig(), o.harness);\n  const raw = applyLayer(withEnv, readRaw(o.path ?? CONFIG_PATH), o.harness);\n  // The harness that ASKED is the correct fallback for an unset `harness` field — not a hardcoded\n  // \"opencode\", whose silent default misfiled every other harness's background seed into an\n  // `opencode::<project>` bank (#3247). An explicit `harness:` in the config file still wins.\n  if (!raw.harness && o.harness) raw.harness = o.harness;\n  return resolveConfig(raw);\n}\n\n/** Bank-resolution fields are meaningless inside a `banks.<id>` section (they can't change the id\n *  that selected it) — strip them so a typo there can't silently re-route memory. */\nconst BANK_OVERRIDE_EXCLUDED = [\n  \"bankId\",\n  \"bankIdTemplate\",\n  \"mapPathToBank\",\n  \"dynamicBankId\",\n  \"resolveWorktrees\",\n  // Approval is decided BEFORE the bank is resolved, so a `banks.<id>` section naming these could\n  // only ever arrive too late to matter — strip them rather than let them read as effective.\n  \"optInOnly\",\n  \"optInPaths\",\n  \"harness\",\n] as const;\n\n/**\n * Apply the `banks.<bankId>` override section (if any) to an already-resolved config — the step\n * that runs AFTER bank resolution, giving per-repo opt-in/out (disable, retainSessions, gitIngest,\n * survey settings, ...) from the ONE global config file.\n */\nexport function applyBankConfig(\n  cfg: Config,\n  resolvedId: string,\n  /** The directory the bank was resolved FROM. Supplying it enforces `optInOnly`; every entry\n   *  point already has it to hand, having just passed it to bank resolution. */\n  directory?: string\n): { cfg: Config; bankId: string } {\n  // Rides the `disabled` gate every entry point already checks after bank resolution, rather than\n  // adding a second thing eight call sites must remember — and that gate is known to stop the run\n  // before anything creates a bank.\n  if (directory !== undefined && !isOptedIn(cfg, directory))\n    return { cfg: { ...cfg, disabled: true }, bankId: resolvedId };\n  const byPath = directory === undefined ? undefined : pathSection(cfg, cfg.paths, directory);\n  if (byPath) {\n    // A path entry never renames the bank: only `banks.<id>` may, below.\n    const { bank: _rename, ...rest } = overrideFields(byPath);\n    cfg = { ...cfg, ...resolvePartial(cfg, rest as RawConfig) };\n  }\n  const section = cfg.banks[resolvedId];\n  if (!section) return { cfg, bankId: resolvedId };\n  const safe = overrideFields(section);\n  // `bank` renames the destination — single hop, selected by the ORIGINAL resolved id (the\n  // target's own banks section, if any, is deliberately NOT consulted: no chaining).\n  const bankId = typeof safe.bank === \"string\" && safe.bank ? (safe.bank as string) : resolvedId;\n  delete safe.bank;\n  return { cfg: { ...cfg, ...resolvePartial(cfg, safe as RawConfig) }, bankId };\n}\n\n/** An override section minus what it may not set: the resolution/approval fields and the nested\n *  maps (a section cannot carry sections of its own). */\nfunction overrideFields(section: object): Record<string, unknown> {\n  const safe: Record<string, unknown> = { ...section };\n  for (const k of BANK_OVERRIDE_EXCLUDED) delete safe[k];\n  delete safe.banks;\n  delete safe.paths;\n  return safe;\n}\n\n/** Resolve just the fields present in `patch`, defaulting against the CURRENT cfg (not the global\n *  defaults) so an override only changes what it names. */\nfunction resolvePartial(cfg: Config, patch: RawConfig): Partial<Config> {\n  const full = resolveConfig(patch);\n  const out: Partial<Config> = {};\n  for (const key of Object.keys(patch) as (keyof RawConfig)[]) {\n    if (key in full)\n      (out as Record<string, unknown>)[key] = (full as unknown as Record<string, unknown>)[key];\n  }\n  // The legacy key resolves into a differently-named field, so the loop above can't carry it.\n  if (\"autoReflect\" in patch && !(\"autoInject\" in patch)) out.autoInject = full.autoInject;\n  // `apiUrl` is derived from `serverMode` + `apiPort`, so an override naming any of the three\n  // re-derives all three against the current cfg: `{ serverMode: \"daemon\" }` alone must also move\n  // the URL to the local daemon, and `{ apiUrl }` under a global daemon mode stays ignored.\n  if (\"serverMode\" in patch || \"apiUrl\" in patch || \"apiPort\" in patch) {\n    const conn = resolveConfig({\n      serverMode: patch.serverMode ?? cfg.serverMode,\n      apiPort: patch.apiPort ?? cfg.apiPort,\n      apiUrl: patch.apiUrl ?? (cfg.serverMode === \"daemon\" ? undefined : cfg.apiUrl),\n    });\n    out.serverMode = conn.serverMode;\n    out.apiUrl = conn.apiUrl;\n    out.apiPort = conn.apiPort;\n  }\n  return out;\n}\n"
    },
    {
      "path": "hindsight-integrations/coding-agents/src/core/knowledge-tools.ts",
      "content": "/**\n * Knowledge-page MCP tool specs — runtime SDK-free so this stays unit-testable without a real MCP\n * host.\n *\n * `src/mcp-server.ts` is the only file with a runtime MCP SDK import; this module uses only its\n * `ToolAnnotations` type. The server wires the specs returned here into an `McpServer`. Each tool\n * wraps one `HindsightClient` knowledge-page/recall method: it never throws — a thrown client error\n * is caught and turned into an `isError:true` text result so the calling LLM sees the failure\n * instead of the process crashing.\n *\n * The agent-facing surface is intentionally curated: grounding + capture only. Raw page CRUD\n * (create/update/delete) is deliberately NOT exposed — agents never author page structure; they\n * capture initiatives (`hindsight_capture_initiative`) and pages are synthesized/maintained by the\n * server. `hindsight_ingest_document` (raw-content retain) also backs the codebase survey\n * (core/survey.ts).\n */\nimport { z } from \"zod\";\nimport { createHash } from \"node:crypto\";\nimport { existsSync } from \"node:fs\";\nimport { homedir } from \"node:os\";\nimport { join } from \"node:path\";\nimport type { ToolAnnotations } from \"@modelcontextprotocol/sdk/types.js\";\nimport type { ZodRawShape } from \"zod\";\nimport type { HindsightClient } from \"./hindsight\";\nimport { syncStatus } from \"./status\";\nimport { applyBankConfig, DEFAULT_REFLECT_TOOL_TIMEOUT_MS, loadConfig } from \"./config\";\nimport { diagFilePath } from \"./diag\";\nimport { describeError } from \"./log\";\nimport type { RetainStamp } from \"./retain-stamp\";\nimport type { PageTrigger } from \"./missions\";\n\nexport interface ToolResult {\n  // Index signature so this structurally satisfies the MCP SDK's CallToolResult (which carries\n  // extra optional fields we don't set) when passed to `McpServer.tool()` in src/mcp-server.ts —\n  // the only file that imports the SDK; this file stays SDK-free.\n  [x: string]: unknown;\n  content: { type: \"text\"; text: string }[];\n  isError?: boolean;\n}\n\ntype ToolSafetyAnnotations = Required<\n  Pick<ToolAnnotations, \"readOnlyHint\" | \"destructiveHint\" | \"idempotentHint\" | \"openWorldHint\">\n>;\n\nconst READ_ONLY_ANNOTATIONS: ToolSafetyAnnotations = {\n  readOnlyHint: true,\n  destructiveHint: false,\n  idempotentHint: true,\n  openWorldHint: false,\n};\n\nconst NON_DESTRUCTIVE_WRITE_ANNOTATIONS: ToolSafetyAnnotations = {\n  readOnlyHint: false,\n  destructiveHint: false,\n  idempotentHint: false,\n  openWorldHint: false,\n};\n\n/**\n * Returned alongside every search result set.\n *\n * Phrased as an obligation triggered by the CALL, not by the agent judging that it \"used\" a page: a\n * model that paraphrases a snippet into its own prose does not register itself as having quoted\n * anything, and silently absorbs the memory instead of crediting it.\n */\nconst CREDIT_REMINDER =\n  \"Crediting is mandatory, not a judgement call: if anything these results contribute reaches your \" +\n  \"reply — quoted, paraphrased, or merely confirming what you were going to say — open that part \" +\n  'with \"> 🧠 **From Hindsight memory (<page>)** — <the specific facts you drew on>\". Rewriting a ' +\n  \"snippet in your own words does not make it yours. If none of them bear on the turn, ignore them \" +\n  \"silently — an unhelpful search needs no mention. These are past records: check a claim that \" +\n  \"something was fixed or works against the code before relying on it.\";\n\nexport interface ToolSpec {\n  name: string;\n  description: string;\n  inputSchema: ZodRawShape;\n  /**\n   * Safety metadata published verbatim as the tool's MCP annotations (src/mcp-server.ts).\n   *\n   * Required, not optional: it is not cosmetic. Dcode gates every MCP tool lacking a coherent\n   * read-only annotation behind an approval prompt, so in its headless (`dcode -n`) runtime an\n   * unannotated tool is REJECTED outright — \"This MCP action requires approval, but the current\n   * headless runtime has no approval UI.\" Codex Auto-review likewise treats an unannotated call as\n   * unverified external access. Reads get READ_ONLY_ANNOTATIONS; the two writes get\n   * NON_DESTRUCTIVE_WRITE_ANNOTATIONS so clients still gate them, but for the right reason.\n   */\n  annotations: ToolSafetyAnnotations;\n  handler: (args: any) => Promise<ToolResult>;\n}\n\nfunction ok(value: unknown): ToolResult {\n  return { content: [{ type: \"text\", text: JSON.stringify(value, null, 2) }] };\n}\n\nfunction err(e: unknown): ToolResult {\n  const message = describeError(e);\n  return { content: [{ type: \"text\", text: JSON.stringify({ error: message }) }], isError: true };\n}\n\n/** Wrap a handler body so a thrown client error always becomes an isError:true result, never a throw. */\nfunction guarded(fn: (args: any) => Promise<unknown>): (args: any) => Promise<ToolResult> {\n  return async (args: any) => {\n    try {\n      return ok(await fn(args));\n    } catch (e) {\n      return err(e);\n    }\n  };\n}\n\n/** Build the knowledge-page + recall MCP tool specs, bound to one client/bank. */\nexport function buildKnowledgeTools(\n  client: HindsightClient,\n  bankId: string,\n  opts: {\n    repoDir?: string;\n    harness?: string;\n    stampFor?: () => RetainStamp;\n    /** Refresh policy for a page `hindsight_capture_initiative` creates (core/missions.ts). */\n    pageTrigger?: PageTrigger;\n    /** How long `hindsight_reflect` waits on the server (cfg.reflectToolTimeoutMs). Must be\n     *  threaded in by every caller: left unset, the client falls back to a 120s deadline that\n     *  aborts high-budget synthesis on a populated bank mid-flight (#3590). */\n    reflectTimeoutMs?: number;\n    /** Reflect budget for `hindsight_reflect` (cfg.reflectBudget, default \"high\"). */\n    reflectBudget?: \"low\" | \"mid\" | \"high\";\n    /** cfg.toolGuideExtra, added after the crediting note so it lands with the results too. */\n    toolGuideExtra?: string;\n  } = {}\n): ToolSpec[] {\n  const extra = opts.toolGuideExtra?.trim();\n  const crediting = extra ? `${CREDIT_REMINDER} ${extra}` : CREDIT_REMINDER;\n  return [\n    {\n      name: \"hindsight_sync_status\",\n      description:\n        \"Report whether this repo's memory bank is in sync: gitlog seed present, how much recent \" +\n        \"history has been deepened with full diffs, conversations ingested, knowledge pages \" +\n        \"created, and extractions still running. `synced: true` means the seeded memory is fully \" +\n        \"queryable. Ingestion is automatic and background — if not synced, it is in progress; \" +\n        \"nothing to run.\",\n      inputSchema: {},\n      annotations: READ_ONLY_ANNOTATIONS,\n      handler: async () => {\n        try {\n          return ok(await syncStatus(client, bankId, opts.repoDir ?? process.cwd()));\n        } catch (e) {\n          return err(e);\n        }\n      },\n    },\n    {\n      name: \"hindsight_diagnose\",\n      description:\n        \"Report safe Hindsight runtime diagnostics for this coding-agent session: resolved bank, \" +\n        \"workspace, harness, config location, API endpoint, and non-secret environment overrides. \" +\n        \"Use this when memory, hooks, MCP tools, or configuration appear not to work. Tokens and \" +\n        \"other secret values are never returned.\",\n      inputSchema: {},\n      annotations: READ_ONLY_ANNOTATIONS,\n      handler: async (_args: Record<string, never>) => {\n        const configPath =\n          process.env.HINDSIGHT_CONFIG || join(homedir(), \".hindsight\", \"coding-agent.json\");\n        const harness = opts.harness ?? \"unknown\";\n        // Resolve through the SAME pipeline the host used — including the `banks.<id>` section for\n        // the bank this client is bound to, which may carry its own apiToken/apiUrl. A bare\n        // loadConfig() would report a mismatch for every per-bank credential.\n        const cfg = applyBankConfig(\n          loadConfig({ harness: opts.harness }),\n          bankId,\n          opts.repoDir\n        ).cfg;\n        return ok({\n          bank_id: bankId,\n          harness,\n          workspace: opts.repoDir ?? process.cwd(),\n          config: {\n            path: configPath,\n            exists: existsSync(configPath),\n            api_url: cfg.apiUrl,\n            api_token_configured: Boolean(cfg.apiToken),\n            disabled: cfg.disabled,\n          },\n          // What the LIVE client is signing with, which is not the same question as what the file\n          // says. A long-lived host used to keep a credential the config had already replaced, and\n          // this tool reported that state as perfectly healthy (#3600). Booleans only — the token\n          // value is never returned.\n          credential: {\n            api_token_in_use: Boolean(client.apiToken),\n            api_token_matches_config: client.apiToken === cfg.apiToken,\n          },\n          environment: {\n            config_override: Boolean(process.env.HINDSIGHT_CONFIG),\n            hooks_disabled: Boolean(process.env.HINDSIGHT_DISABLE_HOOKS),\n            log_level: process.env.HINDSIGHT_LOG_LEVEL ?? null,\n            diagnostics_file: diagFilePath(),\n            channel_id_configured: Boolean(process.env.HINDSIGHT_CHANNEL_ID),\n            user_id_configured: Boolean(process.env.HINDSIGHT_USER_ID),\n          },\n        });\n      },\n    },\n    {\n      name: \"hindsight_search_knowledge_pages\",\n      description:\n        \"Search this repository's Hindsight knowledge pages for content relevant to a query — \" +\n        \"hybrid full-text + semantic search, server-side. Call this when the user's question may \" +\n        \"be answered by the project's accumulated knowledge (architecture, conventions, decisions, \" +\n        \"initiatives) rather than by reading code. Returns ranked pages with a relevance snippet; \" +\n        // Same sentence the payload carries, from the same constant: two copies of a rule this\n        // fiddly drift apart, and the description is what a host shows when the tool is listed.\n        \"read a full page with hindsight_read_knowledge_page. \" +\n        crediting,\n      inputSchema: { query: z.string().describe(\"what to look for\") },\n      annotations: READ_ONLY_ANNOTATIONS,\n      handler: async (args: { query: string }) => {\n        try {\n          // Limit comes from the client (`pageSearchLimit`), so the tool and the hook's injection\n          // can never drift apart — this used to pass its own literal 3.\n          const hits = await client.searchKnowledgePages(args.query);\n          // No `score`. The server fuses BM25 and vector search with reciprocal rank fusion, so the\n          // number is ~1/(60+rank) summed over two retrievers: a perfect top hit scores about 0.03\n          // and nothing ever approaches 1. Handed that, a model reads a strong match as 3% relevant\n          // and discounts it. The hits arrive in rank order, which is the ranking that means\n          // something here.\n          // The reminder rides WITH the hits, not only in the session guide. Measured on real\n          // sessions: the agent searched, got ten on-topic pages, wrote an answer built from them\n          // and credited nothing — then credited correctly the moment the user asked \"where did you\n          // see that?\". The guide had scrolled far up the context by then; the instruction that\n          // lands at the same moment as the results is the one that can still be acted on.\n          return ok({\n            pages: hits.map((h) => ({\n              page: h.name,\n              page_id: h.id,\n              // The question the page answers — the same `description` the list and read tools\n              // carry, so a hit says what the page is FOR, not just how it opens.\n              ...(h.source_query ? { description: h.source_query } : {}),\n              snippet: h.snippet,\n            })),\n            crediting,\n          });\n        } catch (e) {\n          return err(e);\n        }\n      },\n    },\n    {\n      name: \"hindsight_list_knowledge_pages\",\n      description:\n        \"List this repository's Hindsight knowledge pages — curated, continuously-updated \" +\n        \"summaries of the project's durable knowledge (architecture, components, conventions, key \" +\n        \"decisions, and in-flight initiatives). Returns each page's id, title, and a one-line \" +\n        \"description of what it covers. Call this at the start of any non-trivial task, and again \" +\n        \"periodically in long sessions, to see what the project already knows before you read code \" +\n        \"or ask the user. The list changes as work is captured, so re-check it occasionally.\",\n      inputSchema: {},\n      annotations: READ_ONLY_ANNOTATIONS,\n      handler: guarded(async () => client.listPages()),\n    },\n    {\n      name: \"hindsight_read_knowledge_page\",\n      description:\n        \"Read the full content of one knowledge page by its id (from \" +\n        \"hindsight_list_knowledge_pages). Call this whenever a listed page is relevant to what \" +\n        \"you're about to do — e.g. read Conventions before writing new code, Component map before \" +\n        \"changing a subsystem, or an initiative's page before continuing that feature. A page may \" +\n        \"contain [[page:<id>]] links to related pages; follow one by calling this tool again with \" +\n        \"that id. Prefer reading a page over re-deriving the same understanding from source.\",\n      inputSchema: { page_id: z.string() },\n      annotations: READ_ONLY_ANNOTATIONS,\n      handler: guarded(async ({ page_id }) => client.getPage(page_id)),\n    },\n    {\n      name: \"hindsight_reflect\",\n      description:\n        \"Deep memory reasoning: an agentic synthesis over this repository's FULL memory (git \" +\n        \"decisions, past sessions, ingested knowledge) that answers WHY questions — the past \" +\n        \"decision and exact rule/values that explain a behavior, bug, or convention. Slower than \" +\n        \"hindsight_search_knowledge_pages (several seconds): reach for it when pages are too \" +\n        \"shallow and you need the root cause or the decided literals. When the answer informs \" +\n        'your reply, credit it visibly with a blockquote header: \"> 🧠 **From Hindsight memory** — <summary>\".',\n      inputSchema: { query: z.string().describe(\"the question to reason over memory about\") },\n      annotations: READ_ONLY_ANNOTATIONS,\n      handler: guarded(async ({ query }: { query: string }) =>\n        client.reflect(query, {\n          budget: opts.reflectBudget ?? \"high\",\n          timeoutMs: opts.reflectTimeoutMs ?? DEFAULT_REFLECT_TOOL_TIMEOUT_MS,\n        })\n      ),\n    },\n    {\n      name: \"hindsight_capture_initiative\",\n      description:\n        \"Record a new feature or initiative as a tracked knowledge page, so future sessions know it \" +\n        \"exists and can build on it — and keep that page tracking the plan as it moves.\\n\\n\" +\n        \"WHEN TO CALL:\\n\" +\n        \"- Starting one: right after the user approves a plan or finishes brainstorming a new feature/\" +\n        \"capability and you are about to start implementing — BEFORE you write any code. Leave \" +\n        \"relates_to_page_id empty.\\n\" +\n        \"- Plan changed: call it AGAIN — mid-implementation is fine and expected — whenever the goal, \" +\n        \"scope, or rationale of an initiative you already captured materially changes (an approach is \" +\n        \"dropped, scope grows or shrinks, the why is rewritten). Pass relates_to_page_id = that \" +\n        \"initiative's page id so the change lands on the existing page. Never mint a second page for the \" +\n        \"same initiative.\\n\\n\" +\n        \"WHEN TO SKIP: bug fixes, small tweaks, refactors, chores, and trivial course-corrections that \" +\n        \"leave the goal intact are not initiatives — skip them.\\n\\n\" +\n        \"- title: short, specific name (e.g. 'Newsletter refinement chat'). On a recapture, reuse the \" +\n        \"initiative's existing title.\\n\" +\n        \"- summary: 2-3 sentences on what you're building and why — the CURRENT intent, not the \" +\n        \"originally approved plan (on a recapture, say what changed and why).\\n\" +\n        \"- relates_to_page_id: leave empty for a new initiative. Set it to an existing initiative's page \" +\n        \"id — from hindsight_list_knowledge_pages, or the id this tool returned earlier — to record a \" +\n        \"plan change or an enhancement to it.\\n\\n\" +\n        \"Returns the page id. The page is generated for you — you never format one yourself.\",\n      inputSchema: {\n        title: z.string(),\n        summary: z.string(),\n        relates_to_page_id: z.string().optional(),\n      },\n      annotations: NON_DESTRUCTIVE_WRITE_ANNOTATIONS,\n      handler: guarded(async ({ title, summary, relates_to_page_id }) =>\n        client.captureInitiative({\n          title,\n          summary,\n          relatesToPageId: relates_to_page_id,\n          ...(opts.stampFor ? { stamp: opts.stampFor() } : {}),\n          ...(opts.pageTrigger ? { pageTrigger: opts.pageTrigger } : {}),\n        })\n      ),\n    },\n    {\n      name: \"hindsight_ingest_document\",\n      description:\n        \"Save an external document or a block of durable notes/findings into this repository's \" +\n        \"memory so it informs future recall and pages. Use for design notes, research, or \" +\n        \"reference material you want remembered — not for the conversation you're already in \" +\n        \"(that's captured automatically at session end). This is ALSO the correction mechanism: \" +\n        \"when you verify that a retrieved memory is wrong or outdated, ingest a document titled \" +\n        \"'Correction: <topic>' stating what memory claimed, what is actually true, and the \" +\n        \"evidence — the newer fact supersedes the stale one in future retrieval.\",\n      inputSchema: { title: z.string(), content: z.string() },\n      annotations: NON_DESTRUCTIVE_WRITE_ANNOTATIONS,\n      handler: guarded(async ({ title, content }) => {\n        const slug = title\n          .toLowerCase()\n          .replace(/[^a-z0-9]+/g, \"-\")\n          .replace(/^-+|-+$/g, \"\");\n        // ASCII-only slugs erased non-Latin titles (or shared the \"doc\" fallback),\n        // overwriting unrelated documents. Hash the original title, not its content,\n        // so re-ingestion still updates it; \"--\" cannot occur in a legacy slug.\n        const docId =\n          /[^\\x00-\\x7f]/.test(title) || !slug\n            ? `${slug || \"doc\"}--${createHash(\"sha256\").update(title).digest(\"hex\")}`\n            : slug;\n        const stamp = opts.stampFor?.();\n        const metadata = {\n          ...stamp?.metadata,\n          ...(opts.harness ? { harness: opts.harness } : {}),\n        };\n        await client.retain(\n          content,\n          \"ingested document\",\n          docId,\n          [\n            ...new Set([\n              ...(stamp?.tags ?? []),\n              \"source:upload\",\n              ...(opts.harness ? [`harness:${opts.harness}`] : []),\n            ]),\n          ],\n          \"document\",\n          Object.keys(metadata).length ? { metadata } : {}\n        );\n        return { ok: true, doc_id: docId };\n      }),\n    },\n  ];\n}\n"
